(function () {
  'use strict';
  window.QUESTION_BANK = Object.assign(window.QUESTION_BANK || {}, {"punctuation-apostrophes-contractions":{"title":"Apostrophes in Contractions","topic":"Punctuation","questions":[{"id":"punctuation-apostrophes-contractions-q0001","version":2,"contentHash":"sha256:0c39f1d610d2004fbbd985249826a5c0ae63242192ab44035b9fbfb8d6ae911e","question":"Which contraction is spelled correctly?","choices":["does'nt","doesnt","doesn't","do'esnt"],"correct":2,"explanation":{"correct":"Answer: doesn't. A contraction is formed by combining two words and replacing the missing letter with an apostrophe. In 'doesn't', the apostrophe replaces the 'o' in 'not'.","incorrect":[{"choice":"does'nt","category":"misplaced apostrophe","reason":"The apostrophe should replace the missing letter 'o' from the word 'not'. Placing it after the 's' is incorrect because it doesn't represent where the letter was removed."},{"choice":"doesnt","category":"missing apostrophe","reason":"Contractions must include an apostrophe to show that letters have been removed. Without the mark, it looks like a regular word instead of a shortened form of 'does not'."},"",{"choice":"do'esnt","category":"incorrect apostrophe placement","reason":"The apostrophe is placed in the middle of the first word 'does' instead of showing the gap where the 'o' in 'not' was removed. Contractions only use one apostrophe to mark the junction of the two combined words."}]},"studyAid":{"definition":"A contraction is a shortened word made by combining two words into one and using an apostrophe to show where letters have been left out.","example":"is not = isn't, do not = don't, cannot = can't","strategyClue":"Write out the two full words first. Then, cross out the letter that will disappear and place the apostrophe exactly in that empty space between the remaining letters.","link":"https://www.grammar-monster.com/punctuation/apostrophes_for_contractions.html","linkText":"Grammar Monster - Apostrophes in Contractions"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["contractions","apostrophes","word formation"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":1,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0002","version":2,"contentHash":"sha256:9660421a36517015b3b59e32397647fb5ee0b4bf00a7fb265e9c552170fc7c0e","question":"Which is correct?","choices":["I' am","I'am","I'm","Im"],"correct":2,"explanation":{"correct":"Answer: I'm. An apostrophe is used in a contraction to show where a letter has been left out. 'I'm' stands for 'I am', where the 'a' is replaced by the apostrophe.","incorrect":[{"choice":"I' am","category":"incorrect apostrophe placement","reason":"The apostrophe should replace the missing letter, not sit between the two words. 'I' am' splits the words incorrectly."},{"choice":"I'am","category":"apostrophe position error","reason":"The apostrophe must be placed exactly where the letter 'a' was removed. Putting it after the 'I' makes it look like a separate word piece."},"",{"choice":"Im","category":"missing apostrophe","reason":"A contraction requires an apostrophe to show that a letter is missing. Without it, 'Im' looks like a misspelled word."}]},"studyAid":{"definition":"A contraction is a shortened form of two words put together, and an apostrophe shows where a letter or letters have been removed.","example":"do + not = don't; I + am = I'm; it + is = it's","strategyClue":"Write out the full two words first, then identify which letter is being dropped. Place the apostrophe exactly in the spot where that letter used to be.","link":"https://www.grammar-monster.com/punctuation/apostrophes_for_contractions.html","linkText":"Grammar Monster - Apostrophes in Contractions"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["contractions","apostrophes","word formation"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":2,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0003","version":3,"contentHash":"sha256:4a9afc492d34f20bc438133be49079c55d910aac30aab0172d02c90c098c30c2","question":"Which is incorrect?","choices":["can't","wont","won't","isn't"],"correct":1,"explanation":{"correct":"Answer: wont. The word 'wont' refers to a habit or custom and is not a contraction. To write the contraction for 'will not', you must include an apostrophe.","incorrect":[{"choice":"can't","category":"correct contraction usage","reason":"This is a correctly formed contraction of 'cannot'. The apostrophe shows where the letters 'no' were removed."},"",{"choice":"won't","category":"correct contraction usage","reason":"This is the correctly spelled contraction of 'will not'. Even though the spelling changes, the apostrophe is required."},{"choice":"isn't","category":"correct contraction usage","reason":"This is a correctly formed contraction of 'is not'. The apostrophe correctly replaces the missing letter 'o'."}]},"studyAid":{"definition":"Contractions are two words joined together by an apostrophe that takes the place of missing letters.","example":"do not -> don't; I am -> I'm; he is -> he's","strategyClue":"Say the two words you are trying to shorten. If you have removed any letters to make the new word, check that you have inserted an apostrophe at that exact spot.","link":"https://www.grammar-monster.com/punctuation/apostrophes_for_contractions.html","linkText":"Grammar Monster - Apostrophes in Contractions"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["contractions","apostrophes","word formation"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"punctuation-apostrophes-contractions","sequence":3,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0004","version":2,"contentHash":"sha256:06a00fb97e8571512edd68d04151cbb6ec618357799efa1417d27034eb6437d2","question":"Which is correct?","choices":["they're","they'are","they' re","theyr'e"],"correct":0,"explanation":{"correct":"Answer: they're. This is a contraction of the words 'they' and 'are'. The apostrophe takes the place of the missing letter 'a'.","incorrect":["",{"choice":"they'are","category":"double contraction error","reason":"This is incorrect because it tries to keep both the 'a' and the apostrophe. A contraction must remove the letter entirely to replace it with the apostrophe."},{"choice":"they' re","category":"incorrect spacing","reason":"The apostrophe should be placed between the two parts of the word without a space. Putting a space makes the word look like two separate, broken pieces."},{"choice":"theyr'e","category":"misplaced apostrophe","reason":"The apostrophe must replace the 'a' from the word 'are'. Placing it after the 'r' changes the spelling of the root word 'they' incorrectly."}]},"studyAid":{"definition":"A contraction is a shortened form of two words combined into one. Use an apostrophe to show where a letter or letters have been left out.","example":"they are = they're; we are = we're; you are = you're","strategyClue":"Try expanding the contraction back into its two original words in your head. If the sentence still makes perfect sense with 'they are,' then the contraction is correct.","link":"https://www.grammar-monster.com/punctuation/apostrophes_for_contractions.html","linkText":"Grammar Monster - Apostrophes in Contractions"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["contractions","apostrophes","word formation"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":4,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0005","version":3,"contentHash":"sha256:007c824a851ca0fcafdd72c58a71ebdbe45be5da0aeae2cf5091f21b927ef5ef","question":"Which is incorrect?","choices":["shouldn't","should'nt","shouldnt","couldn't"],"correct":1,"explanation":{"correct":"Answer: should'nt. The apostrophe in a contraction replaces the letter 'o' in 'not'. It must be placed between the 'n' and the 't' to be correct.","incorrect":[{"choice":"shouldn't","category":"correct contraction placement","reason":"This is actually the correct way to write the contraction for 'should not.' The apostrophe is placed exactly where the 'o' was removed."},"",{"choice":"shouldnt","category":"missing apostrophe error","reason":"Contractions require an apostrophe to show where a letter has been taken out. Without it, 'shouldnt' is just a misspelled word."},{"choice":"couldn't","category":"correct contraction placement","reason":"This is a correctly spelled contraction. The apostrophe is placed correctly between the 'n' and the 't' for 'could not'."}]},"studyAid":{"definition":"A contraction is a word made by shortening two words, using an apostrophe to show where letters were removed.","example":"do not -> don't; cannot -> can't; it is -> it's","strategyClue":"Expand the contraction back into two separate words to identify where the letter 'o' disappeared, then ensure the apostrophe sits exactly at that gap.","link":"https://www.grammar-monster.com/punctuation/apostrophes_for_contractions.html","linkText":"Grammar Monster - Apostrophes in Contractions"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["contractions","apostrophes","word formation"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"punctuation-apostrophes-contractions","sequence":5,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0006","version":2,"contentHash":"sha256:a374a2dcd2ee13df8d971211980e4bbbcdbfae76487645d0929ec30cb51cdca5","question":"Which is correct?","choices":["it is'nt","it isnt","it's not","its' not"],"correct":2,"explanation":{"correct":"Answer: it's not. An apostrophe replaces the missing 'i' in 'it is', making the contraction 'it's'. The 'not' remains a separate word.","incorrect":[{"choice":"it is'nt","category":"incorrect apostrophe placement","reason":"The apostrophe must replace the missing letter 'o' in 'not'. It should be 'isn't', but placing it after the 's' is incorrect."},{"choice":"it isnt","category":"missing apostrophe","reason":"When you combine 'is' and 'not' into a contraction, you must include an apostrophe to show where the 'o' was removed."},"",{"choice":"its' not","category":"misplaced apostrophe","reason":"'Its' without an apostrophe means belonging to it (possessive). Putting an apostrophe after the 's' is not how contractions are formed."}]},"studyAid":{"definition":"Contractions are two words joined together by an apostrophe that takes the place of missing letters.","example":"it is = it's; is not = isn't; it is not = it's not or it isn't","strategyClue":"Separate the phrase back into its original two words. If the phrase is 'it is', place the apostrophe exactly where the missing 'i' would have been; if it is 'is not', place the apostrophe where the 'o' was removed.","link":"https://www.grammar-monster.com/punctuation/apostrophes_for_contractions.html","linkText":"Grammar Monster - Apostrophes in Contractions"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["contractions","apostrophes","word formation"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":6,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0007","version":2,"contentHash":"sha256:a6bf1d6b02254b43515a647c0e0fdf12b8024de7e63bc45e83e4141ff079ddb5","question":"Which is correct?","choices":["we've","we' ve","wev'e","weve"],"correct":0,"explanation":{"correct":"Answer: we've. This is a contraction of the words 'we have'. The apostrophe correctly takes the place of the missing letters 'h' and 'a'.","incorrect":["",{"choice":"we' ve","category":"incorrect spacing","reason":"Contractions should be written as one single word without any spaces between the letters and the apostrophe."},{"choice":"wev'e","category":"misplaced apostrophe","reason":"The apostrophe must be placed exactly where the omitted letters were removed. Placing it after the 'v' is incorrect."},{"choice":"weve","category":"missing punctuation","reason":"When you combine two words into a contraction, you must use an apostrophe to show that letters have been left out."}]},"studyAid":{"definition":"A contraction is a shortened form of two words combined into one, using an apostrophe to mark the spot where letters were removed.","example":"do not -> don't; I am -> I'm; we have -> we've","strategyClue":"Identify the two original words being combined, then visualize where the letters were taken out and place the apostrophe exactly in that empty gap.","link":"https://www.grammar-monster.com/punctuation/apostrophes_for_contractions.html","linkText":"Grammar Monster - Apostrophes in Contractions"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["contractions","apostrophes","word formation"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":7,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0008","version":3,"contentHash":"sha256:47c4d67dfa3c8c98cc1c947bad5ec83ed5127e68ec5dc2107711063c92143487","question":"Which is incorrect?","choices":["he'll","hell","he'd","he's"],"correct":1,"explanation":{"correct":"Answer: hell. 'Hell' is not a contraction for a pronoun plus a helping verb; it is a separate noun, so it does not belong with correctly written contractions.","incorrect":[{"choice":"he'll","category":"correct contraction","reason":"This is the correct contraction for 'he will.' The apostrophe shows where letters were left out."},"",{"choice":"he'd","category":"correct contraction","reason":"This is a correctly written contraction for 'he had' or 'he would,' so it is not the incorrect choice."},{"choice":"he's","category":"correct contraction","reason":"This is a correctly written contraction for 'he is' or 'he has,' so it is not the incorrect choice."}]},"studyAid":{"definition":"A contraction is a shortened version of two words, using an apostrophe to show where letters have been left out.","example":"he will -> he'll; she will -> she'll; it is -> it's","strategyClue":"Look closely at the connection between the letters and the punctuation mark. A valid contraction must be written as one solid word and include an apostrophe exactly where the missing letters would be.","link":"https://www.grammar-monster.com/punctuation/apostrophes_for_contractions.html","linkText":"Grammar Monster - Apostrophes in Contractions"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["contractions","apostrophes","word formation"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"punctuation-apostrophes-contractions","sequence":8,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0009","version":2,"contentHash":"sha256:6b63a88e6212e5a650bb1cfa66b935b0a2ce1922c0fc47f0b92a3422ec51607b","question":"Which is correct?","choices":["youre","you're","you' re","youre'"],"correct":1,"explanation":{"correct":"Answer: you're. 'You're' is a contraction for 'you are.' The apostrophe takes the place of the missing letter 'a' in 'are'.","incorrect":[{"choice":"youre","category":"missing apostrophe","reason":"This is incorrect because it is missing the necessary apostrophe that signals a contraction. Without the apostrophe, it looks like a word that doesn't exist in English."},"",{"choice":"you' re","category":"improper spacing","reason":"This is incorrect because there should never be a space between the word and the apostrophe. The apostrophe must always be connected directly to the end of the first word."},{"choice":"youre'","category":"misplaced apostrophe","reason":"This is incorrect because the apostrophe is placed at the end of the word rather than replacing the missing 'a' from the word 'are'. It should go between the 'u' and the 'r'."}]},"studyAid":{"definition":"A contraction is a shortened form of two words combined into one, where an apostrophe replaces the missing letters.","example":"you are = you're, it is = it's, do not = don't","strategyClue":"Try expanding the word back into two separate words. If the sentence makes sense when you say 'you are,' you know the contraction needs to show the missing 'a' with punctuation.","link":"https://www.grammar-monster.com/punctuation/apostrophes_for_contractions.html","linkText":"Grammar Monster - Apostrophes in Contractions"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["contractions","apostrophes","word formation"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":9,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0010","version":3,"contentHash":"sha256:ad9b3a4cf6c117f2772bb311a9b7a88947b7a070e595acc001c5ec9dc44a525f","question":"Which is incorrect?","choices":["let's","lets","let's go","let us"],"correct":1,"explanation":{"correct":"Answer: lets. This choice is incorrect because 'lets' is the third-person singular verb meaning 'allows.' The sentence requires a contraction for 'let us,' which must include an apostrophe.","incorrect":[{"choice":"let's","category":"contraction usage","reason":"This is a correct contraction of 'let us,' so it is not the incorrect option for this question."},"",{"choice":"let's go","category":"phrase usage","reason":"This phrase uses the correct contraction for 'let us,' making it a valid choice in many sentences."},{"choice":"let us","category":"formal phrasing","reason":"Using the full words 'let us' is grammatically correct and is simply a more formal way to write the contraction 'let's'."}]},"studyAid":{"definition":"The word 'let's' is a contraction for 'let us' and requires an apostrophe. 'Lets' without an apostrophe is a verb meaning to allow something.","example":"Let's (let us) go home. / She lets (allows) her dog run free.","strategyClue":"Test the word by replacing it with 'let us' in the sentence; if the sentence still makes sense, you must include the apostrophe.","link":"https://www.grammar-monster.com/punctuation/apostrophes_for_contractions.html","linkText":"Grammar Monster - Apostrophes in Contractions"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["contractions","apostrophes","word formation"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"punctuation-apostrophes-contractions","sequence":10,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0011","version":2,"contentHash":"sha256:561c7b26f0689f13c6ce913436a7582afd6d8452f81b4fa8ca693d85e6943230","question":"Which is correct?","choices":["does'nt","doesnt","doesn't","does' not"],"correct":2,"explanation":{"correct":"Answer: doesn't. A contraction combines two words into one by replacing the omitted letter with an apostrophe. 'Does' + 'not' becomes 'doesn't', with the apostrophe placed where the 'o' was removed.","incorrect":[{"choice":"does'nt","category":"misplaced apostrophe","reason":"The apostrophe must replace the missing 'o' from the word 'not'. Placing it after the 'n' is incorrect."},{"choice":"doesnt","category":"missing apostrophe","reason":"Contractions always need an apostrophe to show where letters have been left out. Without one, the word is incomplete."},"",{"choice":"does' not","category":"incorrect contraction usage","reason":"An apostrophe is only used when two words are joined together. You cannot put an apostrophe in the middle of a single word like 'does'."}]},"studyAid":{"definition":"A contraction is a shortened form of two words where an apostrophe replaces the missing letters.","example":"do not -> don't; cannot -> can't; does not -> doesn't","strategyClue":"Write out the two full words first, then identify the exact letter you are removing and place the apostrophe directly in that empty spot.","link":"https://www.grammar-monster.com/punctuation/apostrophes_for_contractions.html","linkText":"Grammar Monster - Apostrophes in Contractions"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["contractions","apostrophes","word formation"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":11,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0012","version":2,"contentHash":"sha256:646a0497c312e912addd52f7bb7c92e75b51a852c581ab641b1432a62def2e90","question":"Which is correct?","choices":["was'nt","wasnt","wasn't","wassn't"],"correct":2,"explanation":{"correct":"Answer: wasn't. The word 'wasn't' is a contraction of 'was not'. The apostrophe must take the place of the missing letter 'o', and it must be placed between the 'n' and the 't'.","incorrect":[{"choice":"was'nt","category":"misplaced apostrophe","reason":"The apostrophe is in the wrong spot; it should sit between the 'n' and the 't', not after the 's'."},{"choice":"wasnt","category":"missing apostrophe","reason":"Contractions require an apostrophe to show where a letter has been removed. Without it, 'wasnt' is missing the essential punctuation mark."},"",{"choice":"wassn't","category":"spelling error","reason":"This choice adds an extra 's' that does not belong in the word. It should be 'was' plus 'n't'."}]},"studyAid":{"definition":"A contraction joins two words together into one, using an apostrophe to replace the letter or letters that were removed.","example":"do not -> don't, cannot -> can't, was not -> wasn't","strategyClue":"Write out the two full words first (e.g., 'was not'), then remove the letter 'o' and replace that gap with an apostrophe.","link":"https://www.grammar-monster.com/punctuation/apostrophes_for_contractions.html","linkText":"Grammar Monster - Apostrophes in Contractions"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["contractions","apostrophes","word formation"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":12,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0013","version":3,"contentHash":"sha256:9a0fb737d8477aa2f7cdf18c0dd980e4bf9917f7e24d69b1babdaeb67d9ca4f7","question":"Which is incorrect?","choices":["could've","could have","could of","couldve"],"correct":2,"explanation":{"correct":"Answer: could of. The phrase 'could of' is incorrect because it confuses the preposition 'of' with the sound of the helping verb 'have' in a contraction. We use the helping verb 'have' to form verb phrases.","incorrect":[{"choice":"could've","category":"correct contraction","reason":"This is the correct way to write the contraction for 'could have'. It uses an apostrophe to show where the letter 'h' and 'a' were removed."},{"choice":"could have","category":"correct verb phrase","reason":"This is the standard, formal way to write the verb phrase. It is perfectly correct to use the two separate words."},"",{"choice":"couldve","category":"missing apostrophe","reason":"When you join two words into a contraction, you must include an apostrophe to replace the missing letters. Without the apostrophe, the word is misspelled."}]},"studyAid":{"definition":"Contractions are two words joined together with an apostrophe. 'Could have' becomes 'could've', never 'could of'.","example":"Correct: 'I could have gone.' / 'I could've gone.' Incorrect: 'I could of gone.'","strategyClue":"Try saying the sentence out loud as two separate words: 'could have.' If 'have' makes sense in the sentence, write it as 'have' or the contraction 've, but never use the word 'of'.","link":"https://www.grammar-monster.com/punctuation/apostrophes_for_contractions.html","linkText":"Grammar Monster - Apostrophes in Contractions"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["contractions","apostrophes","word formation"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"punctuation-apostrophes-contractions","sequence":13,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0014","version":2,"contentHash":"sha256:08eed4b34fdde679ed1bde5a35eac1fd8c4dbf35ac00ddfbb5cdfb6b674b2336","question":"Which is correct?","choices":["she'd","she' d","shed","shed'"],"correct":0,"explanation":{"correct":"Answer: she'd. A contraction uses an apostrophe to show where letters have been removed. In 'she'd', the apostrophe replaces the missing letters in 'had' or 'would'.","incorrect":["",{"choice":"she' d","category":"incorrect apostrophe placement","reason":"An apostrophe should never have a space after it. The parts of a contraction must be written together as one word."},{"choice":"shed","category":"missing apostrophe","reason":"Without an apostrophe, 'shed' is a real word meaning to drop leaves or hair. An apostrophe is required to indicate that this is a contraction for two words."},{"choice":"shed'","category":"misplaced apostrophe","reason":"An apostrophe goes where the missing letters were located. Placing it at the very end of the word is incorrect."}]},"studyAid":{"definition":"Contractions join two words by replacing missing letters with an apostrophe. They help make sentences flow more quickly in informal writing.","example":"she had -> she'd; I am -> I'm; do not -> don't","strategyClue":"Identify the two original words being combined. Write them together, then find exactly where the letters were dropped and place the apostrophe in that specific spot.","link":"https://www.grammar-monster.com/punctuation/apostrophes_for_contractions.html","linkText":"Grammar Monster - Apostrophes in Contractions"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["contractions","apostrophes","word formation"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":14,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0015","version":3,"contentHash":"sha256:9af5c967d19ff0fe83d245c0b808850c34628c0848a3013dc962de43f5e789a4","question":"Which is incorrect?","choices":["mustn't","must'nt","mustnt","must not"],"correct":1,"explanation":{"correct":"Answer: must'nt. The apostrophe must replace the missing letter 'o' in the word 'not' in a contraction. Placing it between the 't' and the 'n' is incorrect because the letter being removed is the 'o' after the 'n'.","incorrect":[{"choice":"mustn't","category":"correct contraction spelling","reason":"This is actually the correct way to write the contraction for 'must not'. The apostrophe correctly takes the place of the letter 'o'."},"",{"choice":"mustnt","category":"missing apostrophe","reason":"Contractions require an apostrophe to show where letters were removed. Without it, the word is just a misspelling."},{"choice":"must not","category":"not a contraction","reason":"This is the full two-word form. It is perfectly correct to write it this way; the question asks for the incorrect contraction form."}]},"studyAid":{"definition":"A contraction is a shortened version of two words, where an apostrophe replaces the letters that were left out.","example":"do not -> don't; cannot -> can't; must not -> mustn't","strategyClue":"Write out the full two words first (must + not). Then, look for the 'o' in 'not' and imagine lifting it out, placing an apostrophe exactly in that empty space.","link":"https://www.grammar-monster.com/punctuation/apostrophes_for_contractions.html","linkText":"Grammar Monster - Apostrophes in Contractions"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["contractions","apostrophes","word formation"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"punctuation-apostrophes-contractions","sequence":15,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0016","version":3,"contentHash":"sha256:17abeda7d3821d1a6e7f484a745464992adcc13f47f7c0bc7989939a7dc3c09d","question":"Which is the contraction for ‘do not’?","choices":["donot","don’t","d’not","doonot"],"correct":1,"explanation":{"correct":"Answer: don’t. A contraction is a shortened form of two words where an apostrophe replaces the omitted letters. In this case, the apostrophe replaces the 'o' in 'not'.","incorrect":[{"choice":"donot","category":"missing apostrophe","reason":"This is simply two words pushed together without an apostrophe. A contraction must include an apostrophe to show where letters have been removed."},"",{"choice":"d’not","category":"incorrect apostrophe placement","reason":"The apostrophe must replace the 'o' in 'not'. Placing it after the 'd' is incorrect because it doesn't accurately represent the removal of letters from the two-word phrase."},{"choice":"doonot","category":"spelling error","reason":"This choice adds an extra 'o' and fails to include the apostrophe. Contractions are meant to shorten words, not make them longer."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":16,"sourceFile":"Basic-1_Mechanics and Punctuation.pdf","sourceQuestionNumber":5,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A contraction is a word made by shortening two words and using an apostrophe to show where letters were taken out.","example":"do not -> don’t, is not -> isn’t, can not -> can’t","strategyClue":"Write the two full words out, cross out the letter you are removing, and place an apostrophe exactly in that empty space to hold the spot.","link":"","linkText":""}},{"id":"punctuation-apostrophes-contractions-q0017","version":4,"contentHash":"sha256:05acafe88127742b48fe35fe25ae22c9a5056e10e10d8b51633b8fb1b92531d5","question":"Choose the correct missing word. I know ________ the right choice.","choices":["your","your’e","youre","you’re"],"correct":3,"explanation":{"correct":"Answer: you’re. This is a contraction of 'you are.' Since the sentence says 'I know you are the right choice,' we need the contraction with an apostrophe.","incorrect":[{"choice":"your","category":"informal abbreviation","reason":"Using the letter 'r' as a word is informal and incorrect in formal writing. Always write out the full word or use the correct contraction."},{"choice":"your’e","category":"misplaced apostrophe","reason":"The apostrophe should replace the missing letter 'a' in 'are,' not be placed after the 'r.' This spelling is incorrect."},{"choice":"youre","category":"missing apostrophe","reason":"Contractions must include an apostrophe to show where letters have been removed. Without it, 'youre' is not a recognized word."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":17,"sourceFile":"Proficient-1_Mechanics and Punctuation.pdf","sourceQuestionNumber":9,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"'You’re' is a contraction of 'you are,' while 'your' shows possession (owning something).","example":"Correct: You’re going to the park. Incorrect: Your going to the park. Correct: Is that your coat?","strategyClue":"Try replacing the word in the blank with the phrase 'you are.' If the sentence still makes sense, you need the version with the apostrophe.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"punctuation-apostrophes-contractions-q0018","version":4,"contentHash":"sha256:06f23af7d7e5d050ea06674ebcefdeb2a00e726133b6a472df2da62ad7fa0fda","question":"Which sentence below uses capitalization correctly? A) Whenever I have time, I go and ride my bike. B) I’ll ask my mom, “will you come with me?” C) she usually stops what she’s doing to take a Bike ride. D) it’s a lot of fun.","choices":["A","B","C","D"],"correct":0,"explanation":{"correct":"Answer: A. Sentences must begin with a capital letter, and the word 'I' must always be capitalized. Choice A correctly capitalizes the first word and follows proper punctuation rules.","incorrect":["",{"choice":"B","category":"improper quotation capitalization","reason":"When a quote is a full sentence, the first word inside the quotation marks should start with a capital letter. 'Will' should be 'Will'."},{"choice":"C","category":"incorrect sentence casing","reason":"The first word of a sentence must always start with a capital letter. 'She' should be 'She', and 'bike' should not be capitalized in the middle of a sentence."},{"choice":"D","category":"missing sentence capitalization","reason":"Every sentence must start with a capital letter. 'It's' should be 'It's' to properly begin the thought."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":18,"sourceFile":"Proficient-2_Mechanics and Punctuation.pdf","sourceQuestionNumber":10,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Always capitalize the first letter of a sentence, the pronoun 'I', and proper nouns.","example":"Correct: I love reading books. Incorrect: i love reading books. Correct: Mom said, \"Hello!\" Incorrect: Mom said, \"hello!\"","strategyClue":"Scan each choice specifically for the first letter of the sentence and the pronoun 'I'. Check if any mid-sentence words are capitalized that shouldn't be.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"punctuation-apostrophes-contractions-q0019","version":2,"contentHash":"sha256:1cc3b016a51c1e9ff069ef696e5ac1779e921030651f38c59a00daefd6fa6b18","question":"Which sentence is written correctly?","choices":["The weatherman said that its going to be a warm day.","The weatherman said that it’s going to be a warm day.","The weatherman said that it going to be a warm day.","The weatherman said that its’ going to be a warm day."],"correct":1,"explanation":{"correct":"Answer: The weatherman said that it’s going to be a warm day. The word 'it's' is a contraction for 'it is'. Since the sentence means 'it is going to be a warm day,' the contraction with an apostrophe is required.","incorrect":[{"choice":"The weatherman said that its going to be a warm day.","category":"possessive versus contraction","reason":"The word 'its' is a possessive pronoun showing ownership. Using it here makes the sentence mean 'the going' belongs to 'it,' which doesn't make sense."},"",{"choice":"The weatherman said that it going to be a warm day.","category":"missing verb","reason":"The sentence needs a linking verb to connect the subject 'it' to the action. Without the 'is' or the contraction 'it's', the sentence is incomplete."},{"choice":"The weatherman said that its’ going to be a warm day.","category":"misused apostrophe","reason":"The form 'its'' is not a word in English. Apostrophes are only used to show ownership or to replace missing letters in a contraction, not to turn a possessive word into one."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":19,"sourceFile":"Proficient-4_Mechanics and Punctuation.pdf","sourceQuestionNumber":2,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Use 'it's' with an apostrophe when you mean 'it is' or 'it has'. Use 'its' without an apostrophe to show that something belongs to a thing.","example":"It's (it is) raining today. The dog wagged its tail (the tail belonging to the dog).","strategyClue":"Replace the word in the sentence with the two words 'it is'. If the sentence still makes sense, you must use the version with the apostrophe.","link":"","linkText":""}},{"id":"punctuation-apostrophes-contractions-q0020","version":2,"contentHash":"sha256:d1b908f4f7088abc494b12755d6ad073c48f99fc87ef3f907e9aeefbb5b08ddf","question":"Choose the sentence with the possessive form.","choices":["The dog buried its bone in the garden.","It’s been a long day.","She’s going to visit New York.","Gary said it’s arrived."],"correct":0,"explanation":{"correct":"Answer: The dog buried its bone in the garden. 'Its' is a possessive pronoun that shows ownership without an apostrophe, just like 'his' or 'her'.","incorrect":["",{"choice":"It’s been a long day.","category":"contraction error","reason":"'It’s' is a contraction for 'it has'. It does not show possession; instead, it indicates an action has occurred."},{"choice":"She’s going to visit New York.","category":"contraction error","reason":"'She’s' is a contraction for 'she is'. This word describes what she is doing, not what she owns."},{"choice":"Gary said it’s arrived.","category":"contraction error","reason":"'It’s' here stands for 'it has'. Since this describes the action of arriving, it is a contraction and not a possessive."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":20,"sourceFile":"Advanced-1_language Usage.pdf","sourceQuestionNumber":4,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A possessive pronoun describes ownership. Contractions use apostrophes to show where letters are missing, such as in 'it is' or 'it has'.","example":"Possessive: The cat licked its paws. Contraction: It's raining outside (It is raining).","strategyClue":"Try replacing the word in the sentence with 'it is' or 'it has'. If the sentence still makes sense, you are looking at a contraction, not a possessive word.","link":"","linkText":""}},{"id":"punctuation-apostrophes-contractions-q0021","version":2,"contentHash":"sha256:9baba4244d9e999814e095dac5a6ea3bc784d8a8f944589c5564e3e8dea8fe6d","question":"Read the selection below. What a day it’s been! My math teacher gave me an award for improving my grades on fractions. Then, the cafeteria served my favorite food – chop suey! This afternoon, the principal announced that I had won a bike. I think this is the best day of my life. This paragraph is probably from a:","choices":["play","book report","poem","diary"],"correct":3,"explanation":{"correct":"Answer: diary. The paragraph is written in the first person ('I', 'my') and describes personal events from a single day, which is the standard format for a diary entry.","incorrect":[{"choice":"play","category":"wrong literary format","reason":"Plays are written as scripts with character names followed by dialogue. This paragraph uses narrative prose to describe personal feelings, not stage directions or dialogue."},{"choice":"book report","category":"wrong literary format","reason":"Book reports focus on analyzing a story or information from a book. This passage is a personal reflection about the writer's own life, not an analysis of a text."},{"choice":"poem","category":"wrong literary format","reason":"Poems usually contain stanzas, line breaks, or rhythmic structure. This selection is written in standard paragraph form, which is typical for journal or diary writing."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":21,"sourceFile":"Advanced-1_language Usage.pdf","sourceQuestionNumber":9,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A diary is a personal record of daily events, thoughts, and feelings written from the perspective of the author.","example":"Dear Diary, today I learned to ride a bike! (Diary); The protagonist felt sad as she walked home. (Story); The characters argued loudly on stage. (Play)","strategyClue":"Look for pronouns like 'I' or 'my' and identify if the text recounts specific personal events from a single day to determine the genre.","link":"","linkText":""}},{"id":"punctuation-apostrophes-contractions-q0022","version":3,"contentHash":"sha256:38b20ef6ec1fea6b23a89516b0a782374aeecf75d05f7a528aadf82d2b284f03","question":"Which group of words uses an abbreviation correctly?","choices":["Mrs. Smith is my boss.","We orderedour pizza w/o olives.","I hate to go to the Dr.’s office.","Don’t you have a dentist appt. today?"],"correct":0,"explanation":{"correct":"Answer: Mrs. Smith is my boss. Titles like 'Mrs.' are correctly abbreviated with a period before the person's name to indicate a shortened title.","incorrect":["",{"choice":"We orderedour pizza w/o olives.","category":"informal texting abbreviations","reason":"Using 'w/o' is considered slang or shorthand for text messaging, not a formal abbreviation. Formal abbreviations should be standard and avoid symbols like slashes."},{"choice":"I hate to go to the Dr.’s office.","category":"incorrect abbreviation usage","reason":"While 'Dr.' is an abbreviation, it is rarely used in formal writing when it is the subject of the office itself. Usually, you would spell out 'doctor' to avoid confusion, and the apostrophe is unnecessary."},{"choice":"Don’t you have a dentist appt. today?","category":"informal writing style","reason":"'Appt.' is a casual shortening of a word. In formal writing, it is better to write the full word 'appointment' to be clear and professional."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":22,"sourceFile":"Advanced-1_language Usage.pdf","sourceQuestionNumber":18,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"An abbreviation is a shortened form of a word or phrase, usually ending with a period to show it is not the full word.","example":"Mr. Jones, St. (Street), Ave. (Avenue), Jan. (January)","strategyClue":"Look at each abbreviation and ask: 'Would I see this written out in a formal letter or a textbook?' If the abbreviation looks like a lazy shortcut or a text message code, it is likely incorrect for formal grammar.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"punctuation-apostrophes-contractions-q0023","version":3,"contentHash":"sha256:d622a333db336a30829dd239475e4e8e007da9e2ca0f00e7913343507c7e19c4","question":"Choose the best missing word. When you go to the movie, don’t _________ on the floor.","choices":["set","be setting","sit","sat"],"correct":2,"explanation":{"correct":"Answer: sit. The word 'sit' means to rest or be in a seated position. Since this is an imperative instruction following 'don’t', the base form of the verb is needed.","incorrect":[{"choice":"set","category":"verb usage error","reason":"'Set' means to place or put something down, not to rest yourself. You would 'set' a bag on the floor, but you 'sit' on a seat."},{"choice":"be setting","category":"incorrect verb tense","reason":"This uses the wrong verb 'set' and an awkward progressive tense that does not fit the simple command structure needed after 'don't'."},"",{"choice":"sat","category":"past tense error","reason":"You cannot use the past tense 'sat' after the helper verb 'don't'. Commands like this require the base form of the verb."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":23,"sourceFile":"Advanced-1_language Usage.pdf","sourceQuestionNumber":28,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"The word 'sit' means to rest yourself on a chair or surface, while 'set' means to place an object somewhere.","example":"I sit in the chair. Please set the book on the table.","strategyClue":"Ask yourself if the action is about resting your own body or placing an object. Then, check that the verb matches the base form required by the word 'don't'.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"punctuation-apostrophes-contractions-q0024","version":2,"contentHash":"sha256:d17cc7b9658856d7f882c2dc65d306bff3502085a7b4ae3e63d9064e923f09cb","question":"Which sentence is punctuated correctly?","choices":["“Then my mom reminded me, ‘Don’t play in the fire,’just before I burned myself,” Tom said.","Then my mom reminded me, “Don’t play in the fire,” just before I burned myself,” Tom said.","“Then my mom reminded me, “Don’t play in the fire,” just before I burned myself,” Tom said.","“Then my mom reminded me, Don’t play in the fire, just before I burned myself,” Tom said."],"correct":0,"explanation":{"correct":"Answer: “Then my mom reminded me, ‘Don’t play in the fire,’ just before I burned myself,” Tom said. This sentence correctly uses double quotation marks to enclose the entire spoken dialogue, and single quotation marks for the inner quote spoken by the mom.","incorrect":["",{"choice":"Then my mom reminded me, “Don’t play in the fire,” just before I burned myself,” Tom said.","category":"missing initial quotation","reason":"This sentence fails to start with a quotation mark at the very beginning of the spoken words. Every piece of dialogue must be enclosed by opening and closing marks."},{"choice":"“Then my mom reminded me, “Don’t play in the fire,” just before I burned myself,” Tom said.","category":"double quotation marks","reason":"When a quote contains another quote, you must use single quotation marks for the inner speech. Using double quotation marks inside double quotation marks is confusing and grammatically incorrect."},{"choice":"“Then my mom reminded me, Don’t play in the fire, just before I burned myself,” Tom said.","category":"missing nested quotes","reason":"The words 'Don't play in the fire' are being spoken by the mom, while the rest of the sentence is spoken by Tom. You must use quotation marks to show exactly where the mom's specific speech begins and ends."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":24,"sourceFile":"Advanced-1_language Usage.pdf","sourceQuestionNumber":32,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Use double quotation marks for direct speech. If the speaker quotes someone else, use single quotation marks inside the double quotation marks.","example":"Sarah said, “He told me, ‘Watch out!’ today.” / “I love reading,” said Leo.","strategyClue":"Look for a quote inside a quote. Identify the outer speaker first, then use a different style of quotation mark to isolate the inner speaker's exact words.","link":"","linkText":""}},{"id":"punctuation-apostrophes-contractions-q0025","version":2,"contentHash":"sha256:bf4ae7c7bbe440b2bfbb428a0b71eec08bea467dfb5e16ce4706f667057435cb","question":"What does the underlined expression mean? You can carry it. Bend at your knees and then pick it up. Easy does it.","choices":["it is notheavy","go slow","I cando it","don’t give up"],"correct":1,"explanation":{"correct":"Answer: go slow. The idiom 'Easy does it' is used to tell someone to move slowly or carefully to avoid making a mistake or dropping something.","incorrect":[{"choice":"it is notheavy","category":"literal interpretation error","reason":"While carrying something light is easy, the expression 'Easy does it' is about the *way* you move, not the weight of the object itself."},"",{"choice":"I cando it","category":"misinterpreting intent","reason":"This phrase sounds like you are cheering for yourself, but 'Easy does it' is a warning to be gentle or careful while performing an action."},{"choice":"don’t give up","category":"idiom confusion","reason":"This is a common mistake! While 'don't give up' encourages someone to keep trying, 'Easy does it' is specifically about moving with caution and control."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":25,"sourceFile":"Advanced-2_language Usage.pdf","sourceQuestionNumber":18,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"The idiom 'Easy does it' is a polite way to tell someone to perform an action slowly, carefully, or gently.","example":"1. Easy does it with that vase; it is very fragile. 2. Easy does it as you pour the hot water into the cup.","strategyClue":"Imagine you are holding something very delicate like a bubble or a stack of cards. What would someone say to make sure you didn't break or spill them?","link":"","linkText":""}},{"id":"punctuation-apostrophes-contractions-q0026","version":2,"contentHash":"sha256:3024276f61b84d755031e1eaaec13370241d8bf1b2b2c06a774115a29696b355","question":"Which sentence is correct?","choices":["Kent don’t got no bike.","Kent doesn’t have a bike.","Kent gots know bike.","K ent not have a bike."],"correct":1,"explanation":{"correct":"Answer: Kent doesn’t have a bike. This sentence uses the correct subject-verb agreement for the singular third-person subject 'Kent' and avoids double negatives.","incorrect":[{"choice":"Kent don’t got no bike.","category":"double negative and agreement","reason":"This sentence uses 'don't' instead of 'doesn't' for a singular subject and contains two negative words ('don't' and 'no'), which is not correct in standard English."},"",{"choice":"Kent gots know bike.","category":"incorrect verb form","reason":"The word 'gots' is not a standard verb form, and 'know' is a verb that means to understand facts, rather than the noun 'no' or 'a' needed to describe possession."},{"choice":"K ent not have a bike.","category":"missing helping verb","reason":"To form a negative sentence in the present tense, you need a helping verb like 'does' with 'not'. Just putting 'not' before 'have' is incomplete."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":26,"sourceFile":"Basic-1_language Usage.pdf","sourceQuestionNumber":25,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Use 'does not' (doesn't) for singular subjects like he, she, or it. A double negative occurs when two negative words are used in one sentence, which should be avoided.","example":"Correct: She doesn't have a pen. Incorrect: She don't got no pen.","strategyClue":"Check if the subject is singular (one person). For singular subjects, look for the 's' sound in the helping verb, and ensure there is only one negative word used to express the lack of something.","link":"","linkText":""}},{"id":"punctuation-apostrophes-contractions-q0027","version":2,"contentHash":"sha256:3f4c548a1485ba642d6db3a5491c3a4a65f0618af66a56554c19bdaa4e28a7ba","question":"Which sentence below is written in Standard English?","choices":["I won’t be able to complete my assignment without the book.","Helen don’t need to help Sam with his math.","Harvey wouldnt’let me borrow his bicycle.","Whose knocking on the door?"],"correct":0,"explanation":{"correct":"Answer: I won’t be able to complete my assignment without the book. This sentence uses correct subject-verb agreement and proper punctuation for the contraction 'won’t'.","incorrect":["",{"choice":"Helen don’t need to help Sam with his math.","category":"subject-verb disagreement","reason":"The subject 'Helen' is singular, so it requires the verb 'doesn’t' instead of 'don’t'. Remember that 'don’t' is only for 'I', 'you', 'we', or 'they'."},{"choice":"Harvey wouldnt’let me borrow his bicycle.","category":"misplaced apostrophe","reason":"The apostrophe in a contraction should go between the 'n' and the 't' (wouldn't). Placing it after the 't' is incorrect punctuation."},{"choice":"Whose knocking on the door?","category":"confused homophones","reason":"'Whose' shows possession, but this sentence needs the contraction 'Who's' (who is) to say who is knocking on the door."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":27,"sourceFile":"Basic-1_language Usage.pdf","sourceQuestionNumber":41,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Standard English requires matching singular subjects with singular verbs and using the correct apostrophes for contractions and possessives.","example":"He doesn't (correct) vs. He don't (incorrect); Who's coming? (correct) vs. Whose coming? (incorrect); Can't (correct) vs. Cant' (incorrect).","strategyClue":"Check each sentence for three things: Does the verb match the subject, is the apostrophe in the correct place for the word, and have you used the right form of homophones like 'whose' vs 'who's'?","link":"","linkText":""}},{"id":"punctuation-apostrophes-contractions-q0028","version":2,"contentHash":"sha256:2b76ac117c17b3af60c72a36177bb6f6d5f1a83249d70e5e1d8c904a47c2702b","question":"Read the following passage and identify the appropriate audience. To install the sink correctly, you need to shutoff the water. If you don’t, the kitchen floor will have water all over it.","choices":["plumbers","mailmen","carpenters","toddlers"],"correct":0,"explanation":{"correct":"Answer: plumbers. This passage provides technical instructions about water shutoff valves and plumbing fixtures. Plumbers are the professionals who specialize in working with water supply systems and installing sinks.","incorrect":["",{"choice":"mailmen","category":"mismatched profession","reason":"Mailmen deliver mail and packages. They do not specialize in installing kitchen sinks or handling residential water shutoff procedures."},{"choice":"carpenters","category":"mismatched profession","reason":"While carpenters work with wood and cabinets, they are not typically responsible for the water pipes and plumbing connections involved in installing a sink."},{"choice":"toddlers","category":"inappropriate audience","reason":"Installing a sink is a complex technical task. It would be unsafe and impossible for a toddler to perform these repairs or understand these instructions."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":28,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":12,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Identifying the audience means determining who is most likely to perform the action or need the information described in the text.","example":"A manual on how to sew a dress is for a tailor; a pamphlet on how to care for a cat is for a pet owner.","strategyClue":"Look at the key action verbs in the passage, such as 'install' and 'shutoff the water.' Ask yourself: 'Who has the job title or skill set required to perform these specific tasks?'","link":"","linkText":""}},{"id":"punctuation-apostrophes-contractions-q0029","version":2,"contentHash":"sha256:e73de3331b6b29f5cc43a169ade5f3096643d644e83834ca386db998cbc88b50","question":"Which sentence is correct?","choices":["I don’t have no pencil.","I have no pencil.","I gots no pencil.","I don’t have a pencil."],"correct":3,"explanation":{"correct":"Answer: I don’t have a pencil. In standard English, we avoid using two negative words in the same clause. 'Don't' already contains a negative, so using 'a' instead of 'no' keeps the sentence grammatically correct.","incorrect":[{"choice":"I don’t have no pencil.","category":"double negative","reason":"This sentence uses two negative words, 'don't' and 'no', which cancel each other out. Standard English rules require only one negative word per thought."},{"choice":"I have no pencil.","category":"style choice","reason":"While this sentence is technically grammatically correct, it is often avoided in simple exercises that focus on the difference between positive/negative contractions and indefinite articles."},{"choice":"I gots no pencil.","category":"non-standard verb form","reason":"The word 'gots' is not a standard English verb form. The correct verb is 'have', and this option also creates a double negative with 'no'."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":29,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":25,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A double negative occurs when two negative words are used in the same sentence, which creates a confusing double-back effect. Stick to one negative word per clause.","example":"Correct: I have no time. Correct: I don't have time. Incorrect: I don't have no time.","strategyClue":"Look for words that mean 'not' or 'none' (like don't, won't, can't, or no/none). Count them in each sentence and choose the one that keeps only one negative idea.","link":"","linkText":""}},{"id":"punctuation-apostrophes-contractions-q0030","version":2,"contentHash":"sha256:98f74e57b23ec6c57a47b13ab2f4ece8f496d3008086f4738a05df8a4851b911","question":"Which contraction is written correctly?","choices":["wo’nt","wasn’t","wer’ent","is’nt"],"correct":1,"explanation":{"correct":"Answer: wasn’t. This contraction combines 'was' and 'not'. The apostrophe replaces the missing 'o' in 'not' and must be placed between the 'n' and the 't'.","incorrect":[{"choice":"wo’nt","category":"incorrect apostrophe placement","reason":"The apostrophe must replace the 'o' in 'not'. Placing it after the 'o' makes the word look incorrect and does not properly show the joining of the two words."},"",{"choice":"wer’ent","category":"incorrect spelling pattern","reason":"The apostrophe should only replace the 'o' in 'not'. Adding it after the 'r' in 'were' is incorrect because the word 'were' is not being shortened here."},{"choice":"is’nt","category":"incorrect apostrophe placement","reason":"The apostrophe must sit between the 'n' and the 't' to show where the 'o' was removed. Placing it before the 'n' breaks the standard spelling rule for contractions."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":30,"sourceFile":"Basic-5_Writing strategies_Application_Style.pdf","sourceQuestionNumber":6,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A contraction is a shortened form of two words where an apostrophe replaces the missing letters. When making a contraction with 'not', the apostrophe always goes between the 'n' and the 't'.","example":"do + not = don't, had + not = hadn't, is + not = isn't","strategyClue":"Write out the two original words first, then cross out the 'o' in 'not' and put an apostrophe exactly in that empty spot.","link":"","linkText":""}},{"id":"punctuation-apostrophes-contractions-q0031","version":2,"contentHash":"sha256:7b0424467419ca8795dc24956fca4153f8705f2ff21a0de5af15f5633ced7678","question":"Which sentence is correctly worded?","choices":["I don’t enjoy eating parsnips or turnips.","Don’t I eating enjoy parsnips or turnips.","Eating I parsnips enjoy don’tor turnips.","Parsnips or turnips don’t I enjoy."],"correct":0,"explanation":{"correct":"Answer: I don’t enjoy eating parsnips or turnips. This sentence follows the standard English word order of Subject-Verb-Object (SVO), beginning with the subject 'I' followed by the verb 'don't enjoy'.","incorrect":["",{"choice":"Don’t I eating enjoy parsnips or turnips.","category":"incorrect word order","reason":"This sentence starts with the verb 'Don't', which creates a question structure. Since this is a statement, the subject 'I' must come before the verb."},{"choice":"Eating I parsnips enjoy don’tor turnips.","category":"jumbled word order","reason":"This sentence places the participle 'Eating' at the start and splits the word 'don't', making the sentence impossible to understand. Always keep the subject-verb pair together."},{"choice":"Parsnips or turnips don’t I enjoy.","category":"object fronting error","reason":"While you can sometimes move objects for emphasis, placing the objects 'Parsnips or turnips' before the subject 'I' creates an awkward, unnatural sentence structure."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":31,"sourceFile":"Basic-6_Writing strategies_Application_Style.pdf","sourceQuestionNumber":6,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A standard English sentence usually follows a specific order: the Subject (who is doing it) comes first, followed by the Verb (the action), and then the Object (what is being acted upon).","example":"Correct: I like cats. Incorrect: Cats I like. Correct: She ate a peach. Incorrect: Ate she a peach.","strategyClue":"Identify the person performing the action and the action itself. Place the 'doer' at the very beginning of the sentence to establish the foundation before adding the remaining details.","link":"","linkText":""}},{"id":"punctuation-apostrophes-contractions-q0032","version":2,"contentHash":"sha256:4867c29e5b189a999639d63625773a7287e0f1d331018ee84566a5fb6dddaa27","question":"Select the best way to complete the sentence below. Unless I study hard, _________________________________________.","choices":["I won’t understand the principles of the math theory.","understanding the principles of the math theory.","because the principles of the math theory are hard to understand.","the principles of the math theory are understanding."],"correct":0,"explanation":{"correct":"Answer: I won’t understand the principles of the math theory. This choice provides a complete main clause with a subject and a verb that logically follows the 'unless' condition.","incorrect":["",{"choice":"understanding the principles of the math theory.","category":"fragmented sentence","reason":"This is a sentence fragment because it lacks a main subject and a conjugated verb to express a complete action or state of being."},{"choice":"because the principles of the math theory are hard to understand.","category":"double conjunction error","reason":"Using 'because' here creates a logical conflict. 'Unless' already sets up the condition, so adding 'because' makes the sentence confusing and grammatically redundant."},{"choice":"the principles of the math theory are understanding.","category":"illogical predication","reason":"This choice says the principles themselves are 'understanding' (an action), which makes no sense. The principles cannot understand anything; the student is the one who understands."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":32,"sourceFile":"Proficient-4_Writing strategies_Application_Style.pdf","sourceQuestionNumber":8,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A complete sentence needs both a subject (who or what the sentence is about) and a verb (the action or state of being) to make sense on its own.","example":"Complete: I will eat. (Subject: I, Verb: will eat). Fragment: Eating the apple. (No subject or conjugated verb).","strategyClue":"Check if your chosen ending has a clear 'doer' of the action and a verb that tells what is happening, ensuring it makes a full statement rather than a description.","link":"","linkText":""}},{"id":"punctuation-apostrophes-contractions-q0033","version":2,"contentHash":"sha256:da81a3ba75d1c954ea5940fa331f806b23fe66d7b82ab1eab758c1a9a995b124","question":"Read the selection below. What a day it’s been! My math teacher gave me an award for improving my grades on fractions. Then, the cafeteria served my favorite food – chop suey! This afternoon, the principal announced that I had won a bike. I thin k this is the best day of my life. This paragraph is probably from a:","choices":["b ook report","poem","play","diary"],"correct":3,"explanation":{"correct":"Answer: diary. A diary is a personal record of daily events, thoughts, and feelings. This paragraph describes specific personal experiences that happened to the author throughout the day.","incorrect":[{"choice":"b ook report","reason":"\"b ook report\" is missing the apostrophe that contractions need to show omitted letters."},{"choice":"poem","category":"incorrect text format","reason":"Poems usually use lines, stanzas, and often rhyme or rhythm, while this text is written in standard prose sentences."},{"choice":"play","category":"incorrect text format","reason":"A play includes dialogue and character names for actors to follow, but this text is a single paragraph written from a first-person perspective."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sequence":33,"sourceFile":"Proficient-4_Writing strategies_Application_Style.pdf","sourceQuestionNumber":9,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A diary is a private journal where a person writes about their daily experiences, feelings, and thoughts in a chronological way.","example":"Dear Diary, today I learned how to ride my bike. I feel so proud of myself because I finally stopped wobbling.","strategyClue":"Look for clues like 'first-person' pronouns ('I', 'my') and specific personal reflections about daily events to identify the genre of a text.","link":"","linkText":""}},{"id":"punctuation-apostrophes-contractions-q0034","version":2,"contentHash":"sha256:b91f648dd971554d4dbd3a9e4249e92afe90454919482b44a25c7da898311de9","question":"Choose the best edited version of the sentence. We’re going too my grandma’s house for Christmas, but we’ll be flying back home on Sunday.","choices":["We’re going to my grandma’s house for Christmas, but we’ll be flying back home on Sunday.","We’re going two my grandma’s house for Christmas, but we’ll be flying back home on Sunday.","Were going to my grandma’s house for Christmas, but we’ll be flying back home on Sunday.","Were going too my grandma’s house for Christmas, but we’ll be flying back home on Sunday."],"correct":0,"explanation":{"correct":"Answer: We’re going to my grandma’s house for Christmas, but we’ll be flying back home on Sunday. 'To' is the correct preposition used to show direction or destination. 'We’re' is the correct contraction for 'we are'.","incorrect":["",{"choice":"We’re going two my grandma’s house for Christmas, but we’ll be flying back home on Sunday.","category":"confused homophones","reason":"'Two' is the number 2. Since you are talking about a destination, you need the preposition 'to'."},{"choice":"Were going to my grandma’s house for Christmas, but we’ll be flying back home on Sunday.","category":"missing apostrophe","reason":"'Were' means something that happened in the past. You need 'We’re' (we are) to show what is happening now."},{"choice":"Were going too my grandma’s house for Christmas, but we’ll be flying back home on Sunday.","category":"homophone and punctuation error","reason":"This choice uses 'Were' (past tense) instead of 'We’re' (we are) and 'too' (which means 'also' or 'excessive') instead of 'to' (direction)."}]},"studyAid":{"definition":"Homophones are words that sound the same but have different meanings and spellings. 'To' indicates direction, 'two' is a number, and 'too' means 'also' or 'very'.","example":"I went to school. I have two dogs. I want to go too.","strategyClue":"Check if the word describes a number, a direction, or an extra amount. Also, verify if the first word is a past-tense verb or a contraction needing an apostrophe.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar and usage","language","grade 4"],"feedbackFocus":"use the grammar rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Advanced Quiz 1_Language_Grammar and Usage_ MAP 4th Grade.pdf","sourceQuestionNumber":9,"sourceCategory":"grammar-and-usage","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":34,"skillIds":[],"standardIds":[]}},{"id":"punctuation-apostrophes-contractions-q0079","version":2,"contentHash":"sha256:c80d74be4a7d6e2e1bc2f6e050cfd43352a9b8f241a4168610722f781c6fd22d","question":"Choose the correct word to complete the sentence. We don’t have any food in the house, so _____ ordering pizza for dinner tonight.","choices":["were","where","there","we’re"],"correct":3,"explanation":{"correct":"Answer: we’re. 'We’re' is a contraction of 'we are.' The sentence needs a subject and a verb to describe an action we are doing, which fits perfectly in this context.","incorrect":[{"choice":"were","category":"verb past tense","reason":"The word 'were' is the past tense form of 'to be.' This sentence is talking about something happening tonight, so the past tense does not make sense."},{"choice":"where","category":"question word","reason":"The word 'where' is used to ask about a place or location. It does not act as a verb or a subject for this sentence."},{"choice":"there","category":"location or expletive","reason":"The word 'there' refers to a place or is used to introduce a thought. It cannot replace the subject-verb contraction needed to show we are ordering pizza."},""]},"studyAid":{"definition":"A contraction is a shortened form of two words written as one with an apostrophe replacing the missing letter(s). 'We’re' is the contraction for 'we are'.","example":"We’re (we are) going home. It’s (it is) time to eat. They’re (they are) coming over.","strategyClue":"Try expanding the word back into two words. If the sentence works with 'we are' inserted into the blank, you need the version with the apostrophe.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar and usage","language","grade 4"],"feedbackFocus":"use the grammar rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Proficient Quiz 2_Language_Grammar and Usage_ MAP 4th Grade.pdf","sourceQuestionNumber":9,"sourceCategory":"grammar-and-usage","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":79,"skillIds":[],"standardIds":[]}},{"id":"punctuation-apostrophes-contractions-q0036","version":3,"contentHash":"sha256:d4ce83877ef8084793ae9ed10f1ef77fda3e8a8e25c2f2860bf43ddd9cebc505","question":"Which punctuation best follows “Wow”? Wow () I can’t believe that I won’the spelling bee!","choices":[".","?",":","!"],"correct":3,"explanation":{"correct":"Answer: !. The word 'Wow' is an interjection used to express strong emotion or surprise. An exclamation point is required to correctly punctuate an interjection that shows excitement.","incorrect":[{"choice":".","category":"period usage","reason":"A period is used to end a standard statement. Since 'Wow' conveys strong emotion rather than just stating a fact, a period is too weak for this sentence."},{"choice":"?","category":"question mark usage","reason":"A question mark is used to show you are asking for information. 'Wow' is not a request for an answer, so a question mark does not fit."},{"choice":":","category":"colon usage","reason":"A colon is used to introduce a list or an explanation. It does not correctly follow an interjection like 'Wow' to show strong feeling."},""]},"studyAid":{"definition":"An interjection is a word used to show sudden strong feeling, such as surprise or excitement. These words are usually followed by an exclamation point.","example":"Ouch! That hurts. / Yay! We won the game. / Oh! I forgot my bag.","strategyClue":"Read the word aloud and listen to your voice. If the word shows strong emotion, look for the punctuation mark that signals excitement rather than a pause or a question.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Advanced Quiz 4_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":2,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":36,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0037","version":3,"contentHash":"sha256:4d0cc55027b839cd49d2634b66a52a6f2753d2edd500ecbfcf83217c8cdc9138","question":"Choose the sentence that contains a punctuation error.","choices":["Cynthia wants to go to a friend’s house after school, but her mother won’t let her.","Dad dashed out the door for work, but forgot his briefcase.","Sami forgot to close the door when she left, so her dog got out.","Christopher and Charles joined the soccer team; Jimmy and Kyle joined the swim team."],"correct":1,"explanation":{"correct":"Answer: Dad dashed out the door for work, but forgot his briefcase. A comma should not separate a compound predicate joined by a conjunction like 'but'. Since 'forgot his briefcase' is not a complete sentence with its own subject, you should remove the comma.","incorrect":[{"choice":"Cynthia wants to go to a friend’s house after school, but her mother won’t let her.","category":"correctly used comma","reason":"This sentence is correct because it uses a comma before the coordinating conjunction 'but' to join two complete, independent sentences."},"",{"choice":"Sami forgot to close the door when she left, so her dog got out.","category":"correctly used comma","reason":"This sentence is correct because it uses a comma before 'so' to join two complete sentences. Each side of the comma has its own subject and verb."},{"choice":"Christopher and Charles joined the soccer team; Jimmy and Kyle joined the swim team.","category":"correct semicolon usage","reason":"This sentence is correct because a semicolon is used to join two closely related independent clauses. Both parts of the sentence are complete thoughts."}]},"studyAid":{"definition":"Use a comma before a coordinating conjunction (for, and, nor, but, or, yet, so) only when it connects two complete sentences. If the second part is just a verb phrase, do not use a comma.","example":"Correct: I ran to the park, and I played soccer. / Incorrect: I ran to the park, and played soccer.","strategyClue":"Check if there is a subject (like 'he', 'she', or 'it') immediately after the conjunction. If there is no subject, you likely do not need a comma.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Advanced Quiz 4_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":3,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":37,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0053","version":3,"contentHash":"sha256:8b76df811ab052ded8e0b7f2e1ef3a8c0fa7409e8245575e2fc3ea1fd59d404a","question":"Choose the word that fits best in the blank and shows the correct punctuation. ___________ don’t forget that you have a pian o lesson after school.","choices":["Sophia","Sophia:","Sop hia,","Sophia;"],"correct":2,"explanation":{"correct":"Answer: Sophia,. When addressing someone directly in a sentence, you must use a comma to separate their name from the rest of the sentence. This is called a direct address.","incorrect":[{"choice":"Sophia","category":"missing comma","reason":"Without a comma after the name, the sentence lacks the necessary pause to show you are addressing Sophia directly."},{"choice":"Sophia:","category":"incorrect punctuation mark","reason":"A colon is used to introduce a list or an explanation, not to address someone. Use a comma for direct address."},"",{"choice":"Sophia;","reason":"Not: Sophia; \"Sophia;\" is missing the apostrophe that contractions need to show omitted letters."}]},"studyAid":{"definition":"When you speak directly to a person by using their name, you must use a comma to separate the name from the message.","example":"Correct: 'Sarah, please sit down.' Incorrect: 'Sarah please sit down.' Correct: 'Good morning, Dad.'","strategyClue":"Imagine you are speaking the sentence aloud. If you naturally pause after saying the person's name, you need to place a comma at that exact spot.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Basic Quiz 2_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":3,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":53,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0081","version":2,"contentHash":"sha256:83ce88c422b4b3b579d6fe0c9bd21592afe700a8c30fe25a7e21368b2aba3b4f","question":"Choose the sentence that is punctuated correctly.","choices":["Before I leave the house each day I grab my lunch.","The dog ran across the yard, and retrieved the frisbee.","I don’t like to watch Hall mark movies but I like Hallmark greeting cards.","Our teacher gave us each a pencil before she gave us the test."],"correct":3,"explanation":{"correct":"Answer: Our teacher gave us each a pencil before she gave us the test. This sentence correctly connects two independent clauses with 'before' without needing a comma, as the subordinating conjunction is in the middle of the sentence.","incorrect":[{"choice":"Before I leave the house each day I grab my lunch.","category":"spelling and punctuation","reason":"This choice contains two spelling errors ('Before' and 'lunch') and is missing a comma after the introductory phrase 'before I leave the house'."},{"choice":"The dog ran across the yard, and retrieved the frisbee.","category":"unnecessary comma usage","reason":"The comma before 'and' is unnecessary because 'retrieved the frisbee' is not a complete sentence; it is just a second verb sharing the same subject, 'the dog'."},{"choice":"I don’t like to watch Hall mark movies but I like Hallmark greeting cards.","category":"compound sentence punctuation","reason":"This is a compound sentence joined by the conjunction 'but'. You must place a comma before 'but' to correctly separate the two independent clauses."},""]},"studyAid":{"definition":"Use a comma before a coordinating conjunction (like 'and', 'but', or 'so') that joins two complete sentences. Do not use a comma when the second part is just an additional verb rather than a whole new sentence.","example":"I ate the pizza, and I felt full. (Comma needed) / I ate the pizza and felt full. (No comma needed)","strategyClue":"Check if there is a subject (like 'I' or 'she') immediately after the conjunction. If there is, you usually need a comma before the conjunction; if there isn't, remove the comma.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Proficient Quiz 1_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":1,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":81,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0104","version":4,"contentHash":"sha256:3213efd3325d40b9c01f13b80d64a213f494e08b6a5882c1d66792f90e2fab26","question":"Which of the following statements would be an example of informal language?","choices":["Excuse me, I am a bit hungry at the moment. Would there be anything to eat?","If it would not be too much trouble, could I get a bite to eat?","Please pass me the mashed potatoes.","I’m really hungry for some turkey and dressing."],"correct":3,"explanation":{"correct":"Answer: I’m really hungry for some turkey and dressing. This sentence uses a contraction ('I'm') and casual phrasing ('really hungry'), which are hallmarks of informal speech used with friends or family.","incorrect":[{"choice":"Excuse me, I am a bit hungry at the moment. Would there be anything to eat?","category":"formal polite phrasing","reason":"This sentence uses 'I am' instead of a contraction and follows a structured, polite request format, which is characteristic of formal or professional language."},{"choice":"If it would not be too much trouble, could I get a bite to eat?","category":"formal structure","reason":"By using 'would not' instead of 'wouldn't' and a complex, polite introductory clause, this sentence maintains a formal tone rather than an informal one."},{"choice":"Please pass me the mashed potatoes.","category":"neutral polite command","reason":"This is a standard, polite imperative sentence. It lacks the conversational 'slang' or relaxed contractions that usually define informal language."},""]},"studyAid":{"definition":"Informal language is the casual way we speak with friends and family, often using contractions and relaxed phrasing, while formal language is more polite, precise, and avoids contractions.","example":"Informal: 'What's up?' vs. Formal: 'How are you doing today?'; Informal: 'I'm gonna go' vs. Formal: 'I am going to go.'","strategyClue":"Look for contractions (like I'm, don't, can't) and simple, everyday words. If the sentence sounds like something you would say to your best friend while hanging out, it is likely informal.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Proficient Quiz 3_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":4,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":104,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0106","version":3,"contentHash":"sha256:d11769f3f90cbb7da78bf9f9fee1995ac49765fa2c3907d79b2cdde230ac5c87","question":"In which section of the following sentence is a word used incorrectly? If you pour juice over you’re video game it will break.","choices":["If you pour juice","over you’re video game","it will break.","no errors"],"correct":1,"explanation":{"correct":"Answer: over you’re video game. The word 'you’re' is a contraction meaning 'you are.' In this sentence, you need the possessive pronoun 'your' to show the game belongs to you.","incorrect":[{"choice":"If you pour juice","category":"correct clause structure","reason":"This part of the sentence is grammatically correct. It includes a capital letter, a subject, and a verb, and there are no spelling errors here."},"",{"choice":"it will break.","category":"correct verb usage","reason":"This phrase is correct as written. It uses the proper future tense 'will' followed by the base form of the verb 'break'."},{"choice":"no errors","category":"identifying spelling errors","reason":"There is a mistake in the sentence. The contraction 'you’re' is used incorrectly where the possessive pronoun 'your' is required."}]},"studyAid":{"definition":"A contraction is a shortened form of two words using an apostrophe (you + are = you're), while a possessive pronoun shows ownership (your).","example":"You're (you are) going to be late. That is your (belongs to you) backpack.","strategyClue":"Try replacing the word in question with the phrase 'you are.' If the sentence stops making sense, you should use the possessive form 'your' instead.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Proficient Quiz 3_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":6,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":106,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0117","version":2,"contentHash":"sha256:e229baf298201edc2fe2f033b42ac2af1855a540b549d7070dae228df6dd2085","question":"Choose the sentence that is punctuated correctly.","choices":["The snake was small black, and s. limy","Th snake slithered across my toes and, mom jumped on top of the table to get away.","I don’t like snakes but I do like spiders.","My favor ite food is chocolate, but I really like potato chips too."],"correct":3,"explanation":{"correct":"Answer: My favor ite food is chocolate, but I really like potato chips too. This sentence uses a comma before the coordinating conjunction 'but' because it connects two independent clauses.","incorrect":[{"choice":"The snake was small black, and s. limy"},{"choice":"Th snake slithered across my toes and, mom jumped on top of the table to get away.","reason":"\"Th snake slithered across my toes and, mom jumped on top of the table to get away.\" is missing the apostrophe that contractions need to show omitted letters."},{"choice":"I don’t like snakes but I do like spiders.","reason":"\"I don’t like snakes but I do like spiders.\" puts the apostrophe in the wrong place for this contraction. A contraction combines words and uses an apostrophe to show where letters were left out."},""]},"studyAid":{"definition":"Use a comma before a coordinating conjunction (like and, but, or) when it joins two complete sentences together.","example":"I wanted to play, but it started to rain. / We could go to the park, or we could watch a movie.","strategyClue":"Read the sentence and find the conjunction. If there is a complete sentence on both sides of that word, you must place a comma before the conjunction.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Proficient Quiz 4_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":7,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":117,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0043","version":2,"contentHash":"sha256:d1205d148b10e44e128a9f7c0707fb86f5b6b9ee0f05eb6e4583490274186b6a","question":"Fill in the blank with the correct word choice. _________ going to make cupcakes for the party?","choices":["Who’s","Whose","Whom","Who"],"correct":0,"explanation":{"correct":"Answer: Who’s. This is a contraction for 'who is.' You can test this by saying 'Who is going to make cupcakes for the party?' which makes perfect sense in this sentence.","incorrect":["",{"choice":"Whose","category":"possessive pronoun confusion","reason":"'Whose' shows ownership, like 'whose backpack is this?' It does not mean 'who is,' so it doesn't fit the action of making cupcakes."},{"choice":"Whom","category":"object pronoun misuse","reason":"'Whom' is used as the object of a verb or preposition. Since the blank is the subject performing the action of 'going to make,' 'who' is needed, not 'whom'."},{"choice":"Who","category":"missing contraction","reason":"'Who' is the subject, but the sentence requires a verb to follow. 'Who going to make' is incomplete; we need the contraction 'Who is' to make the sentence work."}]},"studyAid":{"definition":"The word 'who's' is a contraction of 'who is' or 'who has,' while 'whose' is used to show ownership or belonging.","example":"Who's coming to dinner? (Who is coming); Whose coat is on the chair? (Belonging to someone)","strategyClue":"Try replacing the word in the blank with 'who is.' If the sentence still makes sense, you need the version with the apostrophe.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_ Proficient 1_4th grade.pdf","sourceQuestionNumber":1,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":43,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0044","version":4,"contentHash":"sha256:9c191ae834f67e6a046a506c9a49d9e5b226cef196355c474e2a3693a6cb28f5","question":"Identify which of the following statements would be formal language.","choices":["Th at’s the nicest thing you did for me.","He presented a gift as a gesture of appreciation.","What’s up with your hair?","Hey there, hop in the car if you want a ride."],"correct":1,"explanation":{"correct":"Answer: He presented a gift as a gesture of appreciation. Formal language avoids contractions, slang, and casual greetings, instead using precise vocabulary and complete sentence structures.","incorrect":[{"choice":"Th at’s the nicest thing you did for me.","category":"informal contraction usage","reason":"The use of the contraction 'Th at’s' (short for That is) makes the sentence feel conversational and casual, which is not suitable for formal writing."},"",{"choice":"What’s up with your hair?","category":"slang and contraction","reason":"This sentence uses 'What’s' and the slang phrase 'What’s up,' both of which are common in spoken, informal speech rather than formal writing."},{"choice":"Hey there, hop in the car if you want a ride.","category":"casual greeting usage","reason":"Starting a sentence with 'Hey there' and using the phrasal verb 'hop in' are informal expressions best reserved for talking to friends or family."}]},"studyAid":{"definition":"Formal language is used in professional or academic writing and avoids shortcuts, slang, and overly casual phrasing.","example":"Informal: 'I'm gonna go.' vs. Formal: 'I am going to leave.' Informal: 'Hi!' vs. Formal: 'Dear Sir or Madam,'","strategyClue":"Look for words like contractions (e.g., don't, I'm, it's), slang, or conversational greetings. If you find any of these, the sentence is likely informal.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_ Proficient 1_4th grade.pdf","sourceQuestionNumber":17,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":44,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0045","version":2,"contentHash":"sha256:8e2b501450368ef876607964fa679de0c285a6720e0a17d2048afc6cb5fd99c9","question":"Choose the correct word to complete the sentence. ________ going to have pancakes, bacon, and fruit for breakfast.","choices":["The y’re","There","Their","T he’re"],"correct":0,"explanation":{"correct":"Answer: They're. This is a contraction of the two words 'they' and 'are'. When you are talking about what 'they' are going to do, you use the contraction 'they're'.","incorrect":["",{"choice":"There","category":"confused adverb","reason":"The word 'there' refers to a place or location. Since this sentence describes people eating breakfast, 'there' does not make sense."},{"choice":"Their","category":"possessive pronoun error","reason":"'Their' is used to show ownership, such as 'their breakfast.' It is not a verb, so it cannot be used to mean 'they are'."},{"choice":"T he’re","category":"spelling error","reason":"This is a typo with an extra space. Contractions should always be written as one single word without spaces between the letters."}]},"studyAid":{"definition":"Contractions are two words joined together with an apostrophe replacing the missing letter. 'They're' is the shortened version of 'they are'.","example":"They're hungry. (They are hungry). They're going home. (They are going home).","strategyClue":"Try replacing the word in the blank with the two separate words 'they are'. If the sentence still makes sense, you need the contraction for 'they are'.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_ Proficient 1_4th grade.pdf","sourceQuestionNumber":25,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":45,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0046","version":2,"contentHash":"sha256:09adc148f80789e7eebd02bc2e7dc28455312f41e9ccc622ecf3d0c3e9d29675","question":"Choose the best word to complete the sentence. When the children wouldn’t listen, the teacher became _________________ and took away 10 minutes of their recess.","choices":["elated","agreeable","joyful","agitated"],"correct":3,"explanation":{"correct":"Answer: agitated. The sentence describes a negative situation where children wouldn't listen, causing the teacher to lose patience. 'Agitated' describes someone feeling troubled, annoyed, or restless, which fits the context of taking away recess.","incorrect":[{"choice":"elated","category":"incorrect word spelling","reason":"This is not a real word. 'Elated' is a word, but it means to be very happy, which contradicts the teacher's negative reaction to the children's behavior."},{"choice":"agreeable","category":"opposite word meaning","reason":"To be 'agreeable' means to be pleasant or willing to agree. If the children are not listening, the teacher would not be pleasant or happy with them."},{"choice":"joyful","category":"mismatched emotional tone","reason":"Joyful means very happy. Taking away recess is a consequence for bad behavior, so the teacher would not feel happy or joyful in this situation."},""]},"studyAid":{"definition":"Choosing the right word, or vocabulary word, means picking the term that matches the feeling and tone of the rest of the sentence.","example":"He felt sad when his dog went missing. (Correct) vs. He felt energetic when his dog went missing. (Incorrect)","strategyClue":"Look at the clues in the sentence that describe the situation (like 'wouldn't listen' or 'took away recess'). Decide if the mood is positive or negative, then pick the word that matches that mood.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_ Proficient 1_4th grade.pdf","sourceQuestionNumber":30,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":46,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0052","version":2,"contentHash":"sha256:6328051eb0d57445637fa2f7685a04dfd20f2e1e6cc2db419d581d15dccdd43d","question":"Which the adjective that the word is describes noun this sentence? in My dog, Jimbo, brought me a live lizard yesterday.","choices":["My","live","lizard","there is no adjective in this sentence"],"correct":1,"explanation":{"correct":"Answer: live. Adjectives are words that describe nouns. 'Live' tells us what kind of lizard Jimbo brought, so it is the adjective in the sentence.","incorrect":[{"choice":"My","category":"possessive pronoun","reason":"'My' is a pronoun showing who the dog belongs to, not a word describing the lizard's qualities."},"",{"choice":"lizard","category":"noun identification","reason":"'Lizard' is the noun being described, not the word doing the describing."},{"choice":"there is no adjective in this sentence","category":"missing adjective","reason":"There is a word in the sentence that describes the lizard; look for the word that tells you what type of lizard it is."}]},"studyAid":{"definition":"An adjective is a word that describes or gives more information about a noun (a person, place, or thing).","example":"The fuzzy cat (fuzzy describes cat), a cold drink (cold describes drink), the blue sky (blue describes sky).","strategyClue":"Look for the noun that represents a thing (the lizard) and ask yourself which word in the sentence provides extra detail or describes that thing.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_ Proficient 2_4th grade.pdf","sourceQuestionNumber":1,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":52,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0048","version":2,"contentHash":"sha256:78963ba47b3839c469a4450dc2da07840d45b2a5480ec14cc1a339303a732521","question":"Which answer is a contraction?","choices":["willn’t","them’ll","you’ll","shen’t"],"correct":2,"explanation":{"correct":"Answer: you’ll. A contraction is a word formed by shortening and combining two words, like 'you' and 'will', with an apostrophe replacing the omitted letters.","incorrect":[{"choice":"willn’t","category":"non-standard contraction","reason":"While this looks like a contraction, the standard form is 'won't'. 'Willn't' is not a real English word."},{"choice":"them’ll","category":"invalid word formation","reason":"Contractions are typically formed with pronouns and verbs. 'Them'll' is not a correct way to combine 'them' and 'will'."},"",{"choice":"shen’t","category":"invalid word formation","reason":"This is not a recognized contraction in English. The correct contraction for 'she will not' is 'she won't'."}]},"studyAid":{"definition":"A contraction is a shortened form of two words where an apostrophe is used to show where letters have been left out.","example":"do not -> don't; I am -> I'm; he is -> he's","strategyClue":"Try to expand the word back into two separate words. If the two words make sense together, you have found a real contraction.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_ Proficient 2_4th grade.pdf","sourceQuestionNumber":2,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":48,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0056","version":3,"contentHash":"sha256:d9ac7c8b0a0089939a655cf43337be594e45c1d9bdd2dca02cb754bc3c52d18f","question":"Which line of the address below is incorrect? Mr. and Mrs. Gavely 235 North Bellview Lane Mascoto, MN, 50418","choices":["Mr. and Mrs. Gavely","235 North Bellview Lane","Mascoto, MN, 50418","There are no errors"],"correct":2,"explanation":{"correct":"Answer: Mascoto, MN, 50418. In a standard mailing address, there should be no comma placed between the state abbreviation and the zip code. The correct format is 'City, State Zip Code'.","incorrect":[{"choice":"Mr. and Mrs. Gavely","category":"recipient name format","reason":"This line is correct. Titles like 'Mr.' and 'Mrs.' are used correctly with the family name, and the punctuation is appropriate for the recipient line of an address."},{"choice":"235 North Bellview Lane","category":"street address format","reason":"This line is correct. It properly identifies the street number and name, which is the standard way to write the second line of a mailing address."},"",{"choice":"There are no errors","category":"identifying address errors","reason":"This is incorrect because the third line contains an extra, unnecessary comma between the state abbreviation and the zip code."}]},"studyAid":{"definition":"When writing a mailing address, use a comma to separate the city from the state, but never place a comma between the state and the zip code.","example":"Correct: Springfield, IL 62704; Incorrect: Springfield, IL, 62704","strategyClue":"Look at the punctuation between the two-letter state abbreviation and the five-digit number. Remember that the zip code is a continuation of the location and does not need to be separated by a comma.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_ Proficient 2_4th grade.pdf","sourceQuestionNumber":5,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":56,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0061","version":2,"contentHash":"sha256:2f8e04f159439f3a0383491c48809752c4caa85776e240b4187056b6b46349b7","question":"Which word in this sentence is an adverb? Genevieve carefully took her sleepy sisters up to their bedroom for a nap.","choices":["carefully","sleepy","up","there is not an adverb in this sentence"],"correct":0,"explanation":{"correct":"Answer: carefully. Adverbs describe how, when, or where an action is performed. Here, 'carefully' describes how Genevieve took her sisters to their bedroom.","incorrect":["",{"choice":"sleepy","category":"adjective identification error","reason":"'Sleepy' describes the sisters, which are nouns. Words that describe nouns are adjectives, not adverbs."},{"choice":"up","category":"preposition identification error","reason":"'Up' is used here to show direction toward the bedroom. It is acting as a preposition, not a word that describes how the action was performed."},{"choice":"there is not an adverb in this sentence","category":"missing adverb recognition","reason":"Adverbs often end in '-ly' and explain how an action happens. In this sentence, 'carefully' tells us the manner in which the action was completed."}]},"studyAid":{"definition":"An adverb is a word that modifies a verb, an adjective, or another adverb, often telling us how, when, or where something happens.","example":"He walked slowly (how). The cake was very (intensity) sweet. We left yesterday (when).","strategyClue":"Identify the action verb in the sentence. Ask yourself, 'How was this action done?' The word that provides that description is likely the adverb.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_ Proficient 2_4th grade.pdf","sourceQuestionNumber":10,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":61,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0090","version":2,"contentHash":"sha256:72a28d06af5fb2cb3b3657f54ffb258dd3fad99b119671f4dedef62443b4e6b3","question":"Read the sentence, the context to the that following use clues choose word best fits the meaning of the underlined word. Millie was sad she and her family had to move from their townhouse, but she was happy with her new. residence","choices":["car","home","job","neighbor"],"correct":1,"explanation":{"correct":"Answer: home. The word 'residence' means a place where someone lives. 'Home' is a synonym for residence, making it the best fit for where Millie moved with her family.","incorrect":[{"choice":"car","category":"mismatched context","reason":"A 'residence' is a place where you live, not a vehicle you travel in. Moving a family into a car does not fit the meaning of a residence."},"",{"choice":"job","category":"wrong noun type","reason":"A 'residence' refers to a building or location for living, whereas a 'job' is work you perform. Millie moved from a townhouse, so her new residence must also be a living space."},{"choice":"neighbor","category":"person vs place","reason":"A 'neighbor' is a person who lives near you. Since the sentence discusses Millie moving from a 'townhouse', the missing word must be a place to live, not a person."}]},"studyAid":{"definition":"Synonyms are words that have the same or very similar meanings. Finding a synonym helps you understand new or difficult vocabulary by connecting it to words you already know.","example":"happy (joyful), residence (home), large (big)","strategyClue":"Look at the clues surrounding the unknown word, such as 'townhouse' or 'family', and ask yourself: 'What kind of thing does this sentence describe?' Then, check each option to see if it belongs to that same category.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_ Proficient 2_4th grade.pdf","sourceQuestionNumber":39,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":90,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0091","version":2,"contentHash":"sha256:a281345bd239dc52e04903f8b2b0fd765650c15e45a9ddd0f44efb0b6535041e","question":"Choose the best answer to complete the following sentence. The and elves came out each night to dance under the stars.","choices":["fairy’s","fairys","fairie’s","fairies"],"correct":3,"explanation":{"correct":"Answer: fairies. This sentence requires the plural form of the noun 'fairy.' To make a noun ending in a consonant plus 'y' plural, you change the 'y' to 'i' and add 'es'.","incorrect":[{"choice":"fairy’s","category":"possessive noun error","reason":"The apostrophe makes the word possessive, meaning it belongs to something. We need a plural noun to describe the group of creatures, not something that belongs to one fairy."},{"choice":"fairys","category":"incorrect plural spelling","reason":"You cannot simply add an 's' to a word ending in 'y' that follows a consonant. You must change the 'y' to 'i' before adding 'es'."},{"choice":"fairie’s","category":"plural possessive error","reason":"This form uses both an incorrect spelling and an apostrophe. Since we need a simple plural noun, you do not need an apostrophe at all."},""]},"studyAid":{"definition":"To make most nouns that end in a consonant plus 'y' plural, drop the 'y' and add 'ies'.","example":"party becomes parties, city becomes cities, fly becomes flies.","strategyClue":"Look at the ending of the base word. If it ends in a consonant followed by 'y', ignore the singular form and apply the 'y' to 'i' swap rule before adding the plural suffix.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_ Proficient 2_4th grade.pdf","sourceQuestionNumber":40,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":91,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0103","version":2,"contentHash":"sha256:7a23e78c45f96b249b219f911050d79a7b5ce03e8c46740ed72c73199721948b","question":"Fill in the blank with the correct word choice. _________ are you going to take to the baseball game?","choices":["When","Whose","Whom","Who"],"correct":2,"explanation":{"correct":"Answer: Whom. 'Whom' is the correct choice because it functions as the object of the verb 'take' (you are going to take [someone]).","incorrect":[{"choice":"When","category":"wrong question word","reason":"'When' asks about the time something happens, but the sentence is asking about a person being invited to the game."},{"choice":"Whose","category":"possessive pronoun error","reason":"'Whose' is used to show ownership, not to identify the person receiving an action. It does not fit the structure of this sentence."},"",{"choice":"Who","category":"subject vs object","reason":"'Who' is used when the person is the subject performing the action. Since the person in this sentence is the one being taken, 'whom' is the proper form."}]},"studyAid":{"definition":"Use 'who' when the word is performing the action (the subject), and use 'whom' when the word is receiving the action (the object).","example":"Who wrote this book? / To whom should I give this book?","strategyClue":"Try answering the question. If you would answer with 'he' or 'she', use 'who'. If you would answer with 'him' or 'her', use 'whom'.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Advanced 1_4th grade.pdf","sourceQuestionNumber":1,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":103,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0109","version":2,"contentHash":"sha256:d30fe569fa524b11db48e193a2ebc4c5fa675b86afe7d0ba012a8f94a5a99c2f","question":"Choose the sentence that contains a modal auxiliary verb.","choices":["You shouldn’t wait until the last minute to do your homework.","I want to go to the zoo with my friends next week end.","Everyone needs to look down at their feet when they walk.","That painting is the most beautiful portrait of a sunset."],"correct":0,"explanation":{"correct":"Answer: You shouldn’t wait until the last minute to do your homework. The word 'shouldn't' is a contraction of 'should not,' and 'should' is a modal auxiliary verb used to express advice or obligation.","incorrect":["",{"choice":"I want to go to the zoo with my friends next week end.","reason":"\"I want to go to the zoo with my friends next week end.\" is missing the apostrophe that contractions need to show omitted letters."},{"choice":"Everyone needs to look down at their feet when they walk.","category":"main verb","reason":"The word 'needs' acts as the main verb here. It describes a requirement rather than expressing mood or necessity through an auxiliary verb like 'can,' 'may,' or 'should'."},{"choice":"That painting is the most beautiful portrait of a sunset.","reason":"\"That painting is the most beautiful portrait of a sunset.\" is missing the apostrophe that contractions need to show omitted letters."}]},"studyAid":{"definition":"Modal auxiliary verbs are special helper verbs that express ideas like possibility, necessity, or permission. They are always followed by the base form of another verb.","example":"I can swim (ability), You should sleep (advice), They might arrive soon (possibility).","strategyClue":"Look for a word that helps the main action verb express a 'mood' like ability, permission, or necessity. Try replacing the verb in question with 'can' or 'must'—if it still fits the meaning of the sentence, it is likely a modal.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Advanced 1_4th grade.pdf","sourceQuestionNumber":7,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":109,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0122","version":3,"contentHash":"sha256:6c506933364917aafd4d0317e29ff7f4233f18b54d2d2c7c827ad1763f2f8c92","question":"In which section of the following sentence is a word used incorrectly? T here is a rabbit’s hole in their yard.","choices":["There is a","rabbit’s hole","in their yard.","No errors"],"correct":3,"explanation":{"correct":"Answer: No errors. Every word in the sentence is used correctly: 'There' indicates existence, 'rabbit's' shows possession of the hole, and 'their' correctly identifies that the yard belongs to them.","incorrect":[{"choice":"There is a","category":"homophone usage","reason":"'There' is the correct spelling to show something exists in a specific place. 'Their' would show ownership, and 'they're' is a contraction for 'they are'."},{"choice":"rabbit’s hole","category":"possessive noun","reason":"The apostrophe before the 's' shows that the hole belongs to the rabbit. This is the correct way to show singular possession."},{"choice":"in their yard.","category":"possessive pronoun","reason":"'Their' is the correct possessive pronoun here because it shows the yard belongs to the people mentioned. 'There' or 'they're' would not fit in this context."},""]},"studyAid":{"definition":"Possessive nouns use an apostrophe to show ownership, while homophones like 'there', 'their', and 'they're' must be chosen based on their unique meanings: place, possession, or a contraction.","example":"The dog's bowl (possessive); There is a cat (place); Their house is big (possession); They're happy (contraction).","strategyClue":"Test each word by replacing it: check if 'there' refers to a place, swap 'their' with 'belonging to them', and see if the possessive noun could be rewritten as 'of the'. If all parts meet these checks, look for the 'No errors' option.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Advanced 1_4th grade.pdf","sourceQuestionNumber":20,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":122,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0132","version":2,"contentHash":"sha256:fb792d887a74fabec4917c21c8d5094400e8512f0cfed7b5b405b857328936dd","question":"What does the simile mean in the passage below? Their family was like a patchwork quilt of diversity. They had three adopted children that added something beautiful to their family.","choices":["Like a quilt, the family was old and fragmented. It was probably time to mend the quilt.","Like a quilt that has many different fabrics stitched together, the family had children of different backgrounds that made their family complete.","Like a quilt, they will have the children forever and will love them forever.","Like a quilt from generations past, the family is from generation s past."],"correct":1,"explanation":{"correct":"Answer: Like a quilt that has many different fabrics stitched together, the family had children of different backgrounds that made their family complete. A simile compares two things using 'like' or 'as'. Here, the diverse nature of a patchwork quilt is compared to the diverse backgrounds of the family members.","incorrect":[{"choice":"Like a quilt, the family was old and fragmented. It was probably time to mend the quilt.","category":"incorrect imagery interpretation","reason":"This choice ignores the mention of 'diversity' in the text. Comparing a family to a quilt focuses on the variety of pieces, not on the age or repair of the fabric."},"",{"choice":"Like a quilt, they will have the children forever and will love them forever.","category":"mismatched metaphor meaning","reason":"While loving and permanent, this does not explain the specific comparison to a 'patchwork quilt.' The quilt specifically highlights the variety of parts coming together."},{"choice":"Like a quilt from generations past, the family is from generation s past.","category":"misunderstanding the simile","reason":"This choice focuses on the age of the quilt, whereas the text identifies the quilt as a symbol of 'diversity.' The comparison is about the blend of different types, not the history."}]},"studyAid":{"definition":"A simile is a figure of speech that compares two different things using the words 'like' or 'as' to highlight a specific shared quality.","example":"He is as brave as a lion. The snow was like a white blanket covering the field.","strategyClue":"Look at the noun being described after the simile (in this case, 'diversity'). Determine which answer choice connects the object used for comparison back to that specific noun.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Advanced 1_4th grade.pdf","sourceQuestionNumber":30,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":132,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0155","version":3,"contentHash":"sha256:26a204168ed1bfa6aee9cdc402dec59811177bacfc103b2d29ec9345e29872e2","question":"Which answer is not a contraction?","choices":["shouldn’t","willn’t","doesn’t","haven’t"],"correct":1,"explanation":{"correct":"Answer: willn’t. A contraction is a shortened form of two words combined into one using an apostrophe to replace missing letters. 'Willn’t' is not a standard English contraction; the correct form is 'won’t'.","incorrect":[{"choice":"shouldn’t","category":"common contraction","reason":"This is a contraction of 'should not'. It is a valid word used to make sentences shorter and more conversational."},"",{"choice":"doesn’t","category":"common contraction","reason":"This is a contraction of 'does not'. The apostrophe correctly shows where the letter 'o' was removed."},{"choice":"haven’t","category":"common contraction","reason":"This is a contraction of 'have not'. It follows the standard rule of joining two words and replacing the missing 'o' with an apostrophe."}]},"studyAid":{"definition":"A contraction is a word made by joining two words together and replacing missing letters with an apostrophe.","example":"is not -> isn't, I am -> I'm, could not -> couldn't","strategyClue":"Try splitting each word back into the two original words it represents. If you cannot identify the two words that were joined together, or if the resulting word is not spelled correctly, it is likely not a real contraction.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Advanced 2_4th grade.pdf","sourceQuestionNumber":2,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":155,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0158","version":2,"contentHash":"sha256:7b6dc078a673a4c65161310551a1069c1547aa0b5cb3d3f2040f62ebf570985d","question":"Where is the error in the address below?","choices":["Miss Shawna Russell","50 Monroe Stre.","Dixon, Alabama 42350","There is no error in the address"],"correct":1,"explanation":{"correct":"Answer: 50 Monroe Stre. The abbreviation for 'Street' must be spelled 'St.' or 'Street.' Using 'Stre.' is a misspelling that does not follow standard abbreviation rules.","incorrect":[{"choice":"Miss Shawna Russell","category":"proper noun usage","reason":"This is a person's name and is capitalized correctly. Titles like 'Miss' are used correctly before a name."},"",{"choice":"Dixon, Alabama 42350","category":"city state formatting","reason":"This part of the address follows standard formatting: the city is followed by a comma, the state name, and then the zip code."},{"choice":"There is no error in the address","category":"misspelling identification","reason":"There is actually an error in the word 'Stre.' which is an incorrect way to abbreviate the word Street."}]},"studyAid":{"definition":"Addresses must be written clearly and accurately so mail can be delivered. Words like Street, Avenue, or Road have specific standard abbreviations, such as 'St.', 'Ave.', or 'Rd.'","example":"Correct: 123 Maple St. Incorrect: 123 Maple Stre. Correct: 45 Oak Ave. Incorrect: 45 Oak Aven.","strategyClue":"Look closely at each word in the address to see if any are cut off in a way that doesn't match standard abbreviations. Read each abbreviation out loud to check if it represents the full word correctly.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Advanced 2_4th grade.pdf","sourceQuestionNumber":5,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":158,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0163","version":2,"contentHash":"sha256:9c644285a945e7e311e0d3411c27ec07f56a09a29a6550131b3bd59c557e14da","question":"Which word in this sentence is a modal verb? You should have seen the dog’s face to the dog park! when we got","choices":["should","have","seen","there is not a modal verb in this sentence"],"correct":0,"explanation":{"correct":"Answer: should. 'Should' is a modal verb because it is an auxiliary verb used to express advice or obligation. It changes the meaning of the main verb 'have seen' by adding a sense of expectation.","incorrect":["",{"choice":"have","category":"auxiliary verb confusion","reason":"'Have' is used here as a helping verb to form the present perfect tense, but it does not express possibility or necessity like a modal verb does."},{"choice":"seen","category":"main verb error","reason":"'Seen' is the past participle form of the verb 'see'. It is the main action of the sentence, not a modal verb."},{"choice":"there is not a modal verb in this sentence","category":"misidentifying parts of speech","reason":"There is actually a modal verb present in the sentence. Modal verbs like 'can', 'could', 'should', and 'would' often appear before other verbs to change their meaning."}]},"studyAid":{"definition":"Modal verbs are special helping verbs that express ideas like ability, permission, advice, or necessity. They are always followed by the base form of another verb.","example":"I can run (ability). You should eat (advice). We might go (possibility).","strategyClue":"Look for a word that helps the main verb show obligation or possibility rather than just time. Try replacing the word with 'can' or 'could' to see if the sentence still makes sense.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Advanced 2_4th grade.pdf","sourceQuestionNumber":10,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":163,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0165","version":2,"contentHash":"sha256:ce1c6b9c1a1786234c2838f6e7cbdfd66b3c0ee7030790b30cabea881aac1fd7","question":"Which statement is a fact?","choices":["That sunburn looks like it hurts.","I wonder how many stars there are.","My bedroom is very small.","There is a huge leak in the bathroom."],"correct":1,"explanation":{"correct":"Answer: I wonder how many stars there are. A fact is a statement that can be proven true or false using evidence, observation, or counting. The number of stars can be determined through scientific measurement, making this a factual inquiry.","incorrect":[{"choice":"That sunburn looks like it hurts.","category":"subjective opinion","reason":"This is an opinion because 'looks like it hurts' is based on a person's feelings or personal observation, which can vary from person to person."},"",{"choice":"My bedroom is very small.","category":"subjective descriptor","reason":"This is an opinion because 'very small' is a relative term. What seems small to one person might seem large to someone else."},{"choice":"There is a huge leak in the bathroom.","category":"subjective adjective","reason":"While a leak is a real occurrence, the word 'huge' is an opinion. 'Huge' is not a precise measurement, so this statement cannot be objectively proven true."}]},"studyAid":{"definition":"A fact is a statement that can be proven true or false with evidence. An opinion is a statement of belief, feeling, or preference that cannot be proven.","example":"Fact: The earth revolves around the sun. Opinion: Science is the best subject in school.","strategyClue":"Ask yourself: 'Can I prove this using a ruler, a scale, or a reliable book?' If the sentence uses descriptive words about feelings or sizes that change from person to person, it is likely an opinion.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Advanced 2_4th grade.pdf","sourceQuestionNumber":12,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":165,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0168","version":2,"contentHash":"sha256:6eb0121ab4085442a2d4c5154b2dced1c9f321a85e5a585bd18c9acad234f0c9","question":"What is the meaning of the simile? as poor as dirt","choices":["not very nice to look at","having very little or no money","sleep on the ground because there is not a bed","something is cooked so badly that it tastes like it was made of dirt"],"correct":1,"explanation":{"correct":"Answer: having very little or no money. The simile 'as poor as dirt' compares someone's lack of money to dirt, which is common, cheap, and easy to find everywhere, suggesting a person has nothing of value.","incorrect":[{"choice":"not very nice to look at","category":"incorrect meaning","reason":"This describes something ugly or messy. While dirt is often considered dirty, this simile specifically refers to poverty, not appearance."},"",{"choice":"sleep on the ground because there is not a bed","category":"literal interpretation","reason":"This is a literal interpretation of the word 'dirt.' Similes use figurative language, so we must look for the deeper meaning related to wealth rather than where someone sleeps."},{"choice":"something is cooked so badly that it tastes like it was made of dirt","category":"confusing context","reason":"This confuses the idiom with the literal taste or quality of food. 'Poor' in this context refers to a person's financial situation, not the quality of a meal."}]},"studyAid":{"definition":"A simile is a figure of speech that compares two different things using the words 'like' or 'as' to help create a clear image.","example":"as cold as ice (very cold), as busy as a bee (very active), run like the wind (run very fast)","strategyClue":"Ask yourself if the phrase describes a physical object or a state of being. Think about the word 'poor' and identify which option describes a lack of money rather than a physical appearance or a taste.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Advanced 2_4th grade.pdf","sourceQuestionNumber":15,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":168,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0188","version":2,"contentHash":"sha256:3a2b56cf56eac23e53baea85ec8d587147b2749125ca5df87dfc6b0ddbecfe84","question":"Which sentence shows that there was an accident?","choices":["I did not mean to drop the sugar.","My tire popped when I landed the jump.","The lid snapped closed quickly.","The valve was closed so the water would not run."],"correct":0,"explanation":{"correct":"Answer: I did not mean to drop the sugar. This sentence uses the word 'drop', which describes an accidental action that occurred without intent.","incorrect":["",{"choice":"My tire popped when I landed the jump.","category":"describes a stunt","reason":"Landing a jump on a bicycle or skateboard is a planned activity, so a popped tire here is a result of a stunt rather than an accident like a spill."},{"choice":"The lid snapped closed quickly.","category":"describes mechanism movement","reason":"This describes how a lid moves. A lid snapping shut is an action of the object, not a mistake made by a person."},{"choice":"The valve was closed so the water would not run.","category":"describes intentional design","reason":"This shows a planned action where the valve is closed on purpose to control the water, which is the opposite of an accident."}]},"studyAid":{"definition":"An accident is an event that happens by chance or without intention, often resulting in a mistake or damage.","example":"Oops, I spilled my milk. (accident). I put my toy away. (not an accident).","strategyClue":"Look for words that suggest something went wrong that someone did not plan to happen, like dropping or breaking something by mistake.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Advanced 2_4th grade.pdf","sourceQuestionNumber":35,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":188,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0193","version":2,"contentHash":"sha256:bcd3fc6db0a907184a336af305c426a455e57c1be6049af61c089c0438ffe044","question":"Choose the answer to complete the sentence. best following Do shoes these are? you know","choices":["whose","who’re","who","who’s"],"correct":0,"explanation":{"correct":"Answer: whose. The word 'whose' is a possessive pronoun used to ask who owns an object, such as the shoes. It shows the relationship of ownership between the person and the shoes.","incorrect":["",{"choice":"who’re","category":"contraction confusion","reason":"This is a contraction of 'who are'. If you put it into the sentence, it reads 'who are shoes', which does not make sense because shoes cannot be people."},{"choice":"who","category":"pronoun usage error","reason":"The word 'who' is used as a subject to identify a person. It does not show ownership, so it cannot describe the shoes in this sentence."},{"choice":"who’s","category":"contraction confusion","reason":"This is a contraction of 'who is' or 'who has'. It does not express ownership, so it cannot be used to ask about the shoes in this context."}]},"studyAid":{"definition":"Use 'whose' to ask questions about who owns something. It is different from 'who's', which is a short way to say 'who is'.","example":"Whose bag is this? (ownership) / Who's going to the park? (who is going)","strategyClue":"Replace the blank with the words 'is the owner of the'. If the sentence makes sense with that phrase, you need the possessive word.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Advanced 2_4th grade.pdf","sourceQuestionNumber":40,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":193,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0202","version":2,"contentHash":"sha256:22fcbe9b18fa13a0cf283a3ae304d3cfedd45a867c9eb7203670fc9a725b9f39","question":"Which sentence shows death occurred?","choices":["The treatment for the illness was difficult.","The injury to the woman was fatal.","There was a good chance the man would not survive.","The patient had a quick recovery."],"correct":1,"explanation":{"correct":"Answer: The injury to the woman was fatal. The word 'fatal' means causing or ending in death, which directly answers the prompt.","incorrect":[{"choice":"The treatment for the illness was difficult.","category":"misunderstanding word meaning","reason":"This sentence describes how hard it was to care for an illness, but it doesn't state that the person actually died."},"",{"choice":"There was a good chance the man would not survive.","category":"predicting future events","reason":"This sentence describes a possibility or a risk, but it does not confirm that death has already occurred."},{"choice":"The patient had a quick recovery.","category":"opposite outcome","reason":"A recovery means the patient got better and is no longer sick, which is the opposite of the event mentioned in the prompt."}]},"studyAid":{"definition":"Words have specific meanings; context clues help you determine if an event is a possibility, a process, or a completed action.","example":"Fatal means death occurred. Recovery means the person survived and is healthy again.","strategyClue":"Look for adjectives or outcome words that define the final state of the person. If the word implies the end of life, it matches your target.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Advanced 2_4th grade.pdf","sourceQuestionNumber":49,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":202,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0217","version":2,"contentHash":"sha256:ffcb29f53493f911796564b1a7732f6f8c30becb25a637f39131067ef2c9a6d5","question":"Choose the sentence that is correct.","choices":["There are to many flavors cream to of ice choose from.","There are two many flavors of ice cream to choose from.","There are to many flavors of ice cream too choose from.","There are too many flavors of ice cream to choose from."],"correct":3,"explanation":{"correct":"Answer: There are too many flavors of ice cream to choose from. The word 'too' is used to show an excess or 'a lot of,' and the word 'to' is used to indicate direction or to form an infinitive verb.","incorrect":[{"choice":"There are to many flavors cream to of ice choose from.","category":"jumbled word order","reason":"The words in this sentence are scrambled out of order, making the sentence confusing and grammatically incorrect."},{"choice":"There are two many flavors of ice cream to choose from.","category":"incorrect homophone","reason":"'Two' is a number, not a way to show excess. Use 'too' when you mean 'an excessive amount.'"},{"choice":"There are to many flavors of ice cream too choose from.","category":"confused word usage","reason":"This choice swaps the meanings of 'to' and 'too.' We need 'too' for the amount of flavors and 'to' to start the verb 'choose.'"},""]},"studyAid":{"definition":"'To' is a preposition or part of a verb, while 'too' means 'also' or 'an excessive amount.'","example":"I want to go too (also). That is too (very) much sugar.","strategyClue":"Test the word by replacing it with 'very' or 'excessively.' If the sentence still makes sense, use 'too.' If it refers to movement or action, use 'to.'","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":13,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":217,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0220","version":2,"contentHash":"sha256:9cfc34da9b96fa4fb062d0ed8be80c17f63ad64f84edab86b3ef45239c40cc5b","question":"Choose the correct pronoun to complete the sentence. The teenage boy threw backpack into locker and ran to class. his","choices":["its","his","he","their"],"correct":1,"explanation":{"correct":"Answer: his. We use the possessive pronoun 'his' to show that the backpack belongs to the boy. Because the subject is a singular male, 'his' is the correct choice to show ownership.","incorrect":[{"choice":"its","category":"incorrect possessive pronoun","reason":"'Its' is used to show ownership for an object, animal, or idea, but not for a person. Since we are talking about a boy, 'his' is the correct choice."},"",{"choice":"he","category":"subject pronoun error","reason":"'He' is a subject pronoun used to perform an action. You need a possessive pronoun here to show that the backpack belongs to the boy."},{"choice":"their","category":"pronoun number disagreement","reason":"'Their' is used for plural nouns (more than one person). Since the sentence is about one boy, 'his' is the correct singular possessive pronoun."}]},"studyAid":{"definition":"Possessive pronouns show who or what owns something. Use 'his' for a male, 'her' for a female, and 'its' for an object or animal.","example":"Correct: The boy lost his hat. Incorrect: The boy lost he hat. Correct: The cat licked its paw. Incorrect: The cat licked his paw.","strategyClue":"Identify the noun the pronoun refers to (the boy). Determine if the noun is singular or plural and if it represents a male, female, or object, then pick the pronoun that matches that category.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":16,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":220,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0229","version":2,"contentHash":"sha256:936a702073e9c12cc3227c228d67d78d141a5b7c834f08c2711a86b146ca50e0","question":"Identify the prepositional phrase the sentence in below. There is some milk in the fridge.","choices":["There is","some milk","in the fridge.","The sentence does not contain a prepositional phrase."],"correct":2,"explanation":{"correct":"Answer: in the fridge. A prepositional phrase begins with a preposition (like 'in') and ends with the object of that preposition (the noun 'fridge').","incorrect":[{"choice":"There is","category":"verb phrase error","reason":"'There is' acts as the subject and verb of the sentence, not a prepositional phrase."},{"choice":"some milk","category":"noun phrase error","reason":"'Some milk' is a noun phrase acting as the subject of the sentence, not a prepositional phrase."},"",{"choice":"The sentence does not contain a prepositional phrase.","category":"phrase identification error","reason":"The sentence does contain a prepositional phrase; look for the word that shows position or relationship, such as 'in'."}]},"studyAid":{"definition":"A prepositional phrase is a group of words that begins with a preposition and ends with a noun or pronoun. It describes where, when, or how something happens.","example":"on the table, under the rug, during the game","strategyClue":"Look for a word that shows a relationship between two things, such as 'in', 'on', 'at', or 'by'. Once you find that word, look for the noun that follows it to complete the phrase.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":25,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":229,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0235","version":2,"contentHash":"sha256:ffdc52a2f423c194cac5467df2aa5bc84a86a5ddecb98ce43495ac54d61715a3","question":"Which noun is plural? We went hiking through the desert, and there were cacti everywhere.","choices":["hiking","desert","cacti","everywhere"],"correct":2,"explanation":{"correct":"Answer: cacti. A plural noun refers to more than one person, place, or thing. 'Cacti' is the irregular plural form of the singular noun 'cactus'.","incorrect":[{"choice":"hiking","category":"verb form error","reason":"'Hiking' is an action word (verb) ending in -ing, not a noun. Plural nouns represent things, not actions."},{"choice":"desert","category":"singular noun usage","reason":"'Desert' is a singular noun because it refers to only one specific place. Plural nouns require more than one item."},"",{"choice":"everywhere","category":"adverb of place","reason":"'Everywhere' is an adverb that describes where something happened, not a noun that can be pluralized."}]},"studyAid":{"definition":"A plural noun indicates that there is more than one of something. While many nouns end in -s or -es to become plural, some irregular nouns change their spelling entirely.","example":"dog -> dogs; box -> boxes; cactus -> cacti; mouse -> mice","strategyClue":"Ask yourself if the word represents a single object or multiple objects. If you can have 'two' or 'many' of the thing, check if the word structure signifies that it is not just a singular item.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":31,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":235,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0238","version":2,"contentHash":"sha256:4c9ea32f060fe252e0b6fea12b212ab9a9266ea4266921185ce1ee5baa40c428","question":"Fill in the blank with the correct word choice. My bike, has a broken seat, is in the garage.","choices":["that","who","whose","which"],"correct":3,"explanation":{"correct":"Answer: which. We use 'which' to introduce non-restrictive clauses, which add extra information to a sentence and are set off by commas.","incorrect":[{"choice":"that","category":"relative pronoun usage","reason":"The word 'that' is used for restrictive clauses that provide essential information and do not require commas. Because this sentence has commas, 'which' is the correct choice."},{"choice":"who","category":"wrong pronoun reference","reason":"'Who' is used only for people. Since a bike is an object, not a person, 'who' cannot be used to describe it."},{"choice":"whose","category":"incorrect possessive form","reason":"'Whose' is used to show ownership, such as 'The girl whose bike is broken.' It does not fit here because we are describing the bike itself, not what it owns."},""]},"studyAid":{"definition":"Relative pronouns connect a description to a noun. 'Which' is used for things, 'who' for people, and 'whose' for possession.","example":"The dog, which is brown, likes to run. The boy who lives next door is nice. The house whose roof is red is mine.","strategyClue":"Look at the commas around the blank and determine if the noun being described is a person or an object. Use 'which' for objects when the information is extra and separated by commas.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":34,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":238,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0246","version":2,"contentHash":"sha256:84e6ddea96d33462ea432972e8df8e1e8ce42e1726885d1aa31fd6ce4e201814","question":"Which sentence demonstrates correct subject-verb agreement?","choices":["The girls is walking class to the from gym.","My son are taking too long to return my phone call.","The playing kickball children is during recess.","People in the city honk their horn a lot."],"correct":3,"explanation":{"correct":"Answer: People in the city honk their horn a lot. The subject 'People' is plural, so it requires the plural verb form 'honk' to agree.","incorrect":[{"choice":"The girls is walking class to the from gym.","category":"subject-verb disagreement","reason":"The subject 'The girls' is plural, so it must pair with 'are walking' instead of 'is walking'. Also, the word order in the phrase 'class to the from gym' is mixed up."},{"choice":"My son are taking too long to return my phone call.","category":"subject-verb disagreement","reason":"The subject 'My son' is singular, so it should be paired with the singular verb 'is taking'. 'Are taking' is only for plural subjects like 'we' or 'they'."},{"choice":"The playing kickball children is during recess.","category":"subject-verb disagreement","reason":"The subject 'children' is plural, which requires the plural verb 'are'. Furthermore, the word order makes it sound as if the children themselves are the recess, rather than the children playing."},""]},"studyAid":{"definition":"Subject-verb agreement means that a singular subject needs a singular verb, and a plural subject needs a plural verb.","example":"The dog barks (singular). The dogs bark (plural). She walks home. They walk home.","strategyClue":"Identify the subject of the sentence first. Ask yourself if there is only one person/thing or more than one, then choose the verb that matches that count.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":42,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":246,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0247","version":2,"contentHash":"sha256:e3b09242986312275564f58b554960b9231a859a6da8e6f8fc5ef1b64f097c9b","question":"Identify the correct word that goes in the blank. are too many people wandering the hall ways.","choices":["Their","They’re","There","Thier"],"correct":2,"explanation":{"correct":"Answer: There. 'There' is used to indicate the existence or presence of something, which is correct when talking about the number of people in the hallway.","incorrect":[{"choice":"Their","category":"possessive pronoun confusion","reason":"'Their' is used to show ownership, like 'their backpacks.' It doesn't work here because we aren't talking about something the people own."},{"choice":"They’re","category":"contraction confusion","reason":"'They’re' is a contraction for 'they are.' If you replace it in the sentence, it reads 'They are are too many people,' which does not make sense."},"",{"choice":"Thier","category":"misspelled word","reason":"'Thier' is not a correct English word. The letters 'i' and 'e' are swapped, making it an incorrect spelling."}]},"studyAid":{"definition":"'There' refers to a place or existence, 'their' shows possession (belonging to them), and 'they’re' is a contraction for 'they are'.","example":"There is a cat. (existence); That is their cat. (possession); They’re feeding the cat. (they are).","strategyClue":"Try replacing the word in the blank with 'they are.' If the sentence still makes sense, choose the contraction. If you are talking about a location or a quantity of items, use the spelling that ends in 'ere'.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":43,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":247,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0254","version":2,"contentHash":"sha256:5558cc7a802713a8fb2d37d1d27d5057721e2ebf88c291d1be2a1ea0d1dee0c4","question":"In section the sentence a incorrectly? which of following is word used I think there is the meanest dog in the neighborhood. dog","choices":["I think","there dog is the","meanest dog in","the neighborhood."],"correct":1,"explanation":{"correct":"Answer: there dog is the. This option corrects the word order so that the verb 'is' correctly links the subject 'dog' to its descriptor, forming the phrase 'the meanest dog is there' or adjusting the syntax to place the subject and verb in the proper relationship.","incorrect":[{"choice":"I think","category":"subject-verb phrase","reason":"The phrase 'I think' is grammatically correct as an introductory clause and is not the source of the word order error in the sentence."},"",{"choice":"meanest dog in","category":"superlative phrase","reason":"The phrase 'meanest dog in' correctly uses the superlative adjective to describe the dog and is not the part of the sentence where the words are misplaced."},{"choice":"the neighborhood.","category":"prepositional phrase","reason":"The phrase 'the neighborhood.' is a correctly placed prepositional phrase identifying the location and does not contain the word order error."}]},"studyAid":{"definition":"A complete sentence requires a clear subject followed by a verb that describes what the subject is or does.","example":"Correct: The dog is mean. Incorrect: Is mean the dog.","strategyClue":"Identify the main subject (who or what the sentence is about) and the verb (what is happening). Try rearranging the word groups to ensure the subject comes before the action or state of being.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":50,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":254,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0265","version":2,"contentHash":"sha256:a1d078d76909c859f8083a6046483a4905f08502f20371f2c5203fcabff5bbec","question":"Choose the correct pronoun to complete the sentence below. The dogs shared their food with the cat, but didn’t like it.","choices":["he","them","him","they’s"],"correct":0,"explanation":{"correct":"Answer: he. The pronoun 'he' is the subject pronoun needed to perform the action of 'liking' in the second part of the sentence. Since the dog is a singular noun, 'he' correctly takes its place.","incorrect":["",{"choice":"them"},{"choice":"him","reason":"\"him\" is missing the apostrophe that contractions need to show omitted letters."},{"choice":"they’s","reason":"\"they’s\" puts the apostrophe in the wrong place for this contraction. A contraction combines words and uses an apostrophe to show where letters were left out."}]},"studyAid":{"definition":"Subject pronouns (like he, she, it, they) perform the action, while object pronouns (like him, her, it, them) receive the action.","example":"He ran (correct) vs. Him ran (incorrect); She saw them (correct) vs. She saw they (incorrect).","strategyClue":"Identify the verb in the second part of the sentence. Ask yourself, 'Who or what is performing this action?' If the pronoun is doing the action, pick the subject form.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Basic 2_4th grade.pdf","sourceQuestionNumber":10,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":265,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0271","version":2,"contentHash":"sha256:02809e26a21892116b3fe421e5197d0cc05357079bfb015b03b78e5399d2b047","question":"Choose the correct word for the sentence below. Everyone brought their homework to c lass except.","choices":["she","me","they","I"],"correct":1,"explanation":{"correct":"Answer: me. The word 'except' is a preposition, and objects of prepositions must use object pronouns like 'me', not subject pronouns like 'I', 'she', or 'they'.","incorrect":[{"choice":"she","category":"subject pronoun error","reason":"The word 'she' is a subject pronoun. Because it follows the preposition 'except', you must use an object pronoun instead."},"",{"choice":"they","category":"subject pronoun error","reason":"The word 'they' is used for the subject of a sentence. It cannot follow a preposition like 'except', which requires an object pronoun."},{"choice":"I","category":"subject pronoun error","reason":"The word 'I' is a subject pronoun. It should only be used when doing the action, not after a preposition like 'except'."}]},"studyAid":{"definition":"Prepositions are words that show relationships, and they must be followed by object pronouns like me, you, him, her, it, us, or them.","example":"Correct: Everyone played except me. Incorrect: Everyone played except I. Correct: Sit beside her. Incorrect: Sit beside she.","strategyClue":"Identify the word before the blank as a preposition. Ask yourself, 'Does this word describe who is receiving the action?' If it does, pick the pronoun form used for objects.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Basic 2_4th grade.pdf","sourceQuestionNumber":16,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":271,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0285","version":3,"contentHash":"sha256:f0d3324c481224ca482c335607499e21484fea0952abd440f3254c8b373503e1","question":"Choose the transition that intro duces a new idea. I want to add tomato plants to my garden this year., I want to pu t a fence up to help keep rabbits out.","choices":["Therefore","Also","Obviously","Briefly"],"correct":1,"explanation":{"correct":"Answer: Also. The word 'also' is a transition word used to add a new point or idea to the conversation. Since the second sentence adds another task for the garden, 'also' creates a smooth connection.","incorrect":[{"choice":"Therefore","category":"cause and effect","reason":"This transition shows that the second sentence is a result of the first. Putting up a fence isn't a result of wanting tomato plants, so this doesn't fit the relationship between the ideas."},"",{"choice":"Obviously","category":"unnecessary emphasis","reason":"This word is used to suggest that something is easy to see or understand. Using it here doesn't help connect the two different tasks you want to do in the garden."},{"choice":"Briefly","category":"time or summary","reason":"This transition is used when you are about to summarize information or speak for a short time. Since you are just listing another goal for your garden, this choice is not appropriate."}]},"studyAid":{"definition":"Transition words are like bridges that connect your ideas so your writing flows smoothly. Choosing the right one helps the reader understand how your sentences relate to each other.","example":"Adding ideas: also, in addition, furthermore. Showing results: therefore, so, as a result.","strategyClue":"Ask yourself: 'Is the second sentence adding information, showing a result, or contrasting?' Look for words that match that specific job.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Basic 2_4th grade.pdf","sourceQuestionNumber":30,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":285,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0298","version":2,"contentHash":"sha256:3499aee80a22ba04c537f3134c59a72bc257c4e5ae3a2b1c31b77661a5d07ed2","question":"Which answer is a possessive pronoun?","choices":["him","ours","me","they"],"correct":1,"explanation":{"correct":"Answer: ours. A possessive pronoun is used to show ownership without needing to repeat the noun. 'Ours' shows that something belongs to us.","incorrect":[{"choice":"him","category":"object pronoun","reason":"'Him' is an object pronoun used when someone is receiving an action. It does not show that something belongs to a person."},"",{"choice":"me","category":"object pronoun","reason":"'Me' is an object pronoun used to refer to yourself as the receiver of an action. It cannot show ownership."},{"choice":"they","category":"subject pronoun","reason":"'They' is a subject pronoun used when someone is performing an action. It is used to name the people, not to show what they own."}]},"studyAid":{"definition":"Possessive pronouns are words that replace a noun to show who or what owns it. They help you avoid repeating the same name over and over.","example":"This book is mine (not me). That ball is hers (not her). The car is ours (not us).","strategyClue":"Ask yourself, 'Does this word describe who owns an object?' If you can answer 'whose is it?' with the word, it is likely a possessive pronoun.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Basic 2_4th grade.pdf","sourceQuestionNumber":43,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":298,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-contractions-q0301","version":2,"contentHash":"sha256:fb0355e306ae895364fc339cd96981f705aaff032a435556b350d27a8232fcdd","question":"Which word correctly completes the following sentence? The new bab y birds were chirping for mother.","choices":["they","they’s","their","their’s"],"correct":2,"explanation":{"correct":"Answer: their. 'Their' is a possessive pronoun that shows the baby birds belong to or are associated with the mother bird. It correctly shows possession in this context.","incorrect":[{"choice":"they","category":"subject pronoun usage","reason":"'They' is a subject pronoun used to perform an action. You cannot use 'they' to show possession; it does not make sense to say 'they mother'."},{"choice":"they’s","category":"incorrect possessive form","reason":"'They’s' is not a word in the English language. When showing ownership for 'they', we always use the word 'their'."},"",{"choice":"their’s","category":"unnecessary apostrophe","reason":"'Their' is already a possessive word, so it does not need an apostrophe. Adding one creates an incorrect form."}]},"studyAid":{"definition":"The word 'their' is a possessive pronoun used to show that something belongs to a group. It describes 'whose' something is.","example":"The dog wagged its tail. The birds fed their chicks. The students opened their books.","strategyClue":"Replace the word in the blank with 'his' or 'her' to see if it makes sense. If ownership is being described, choose the possessive pronoun rather than a subject pronoun or a made-up word.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-contractions","sourceFile":"Language Usage_Basic 2_4th grade.pdf","sourceQuestionNumber":46,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":301,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, then nearby grade-appropriate practice to fill the configured mission length"}}}
  );
})();
